begin;
create table if not exists public.pro_schedule_templates(owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,name text not null check(length(btrim(name)) between 1 and 80),notes text not null check(length(notes)<=1000),revision integer not null check(revision>0),archived boolean not null default false,primary key(owner_id,id));
create table if not exists public.pro_schedule_template_phases(owner_id uuid not null,template_id uuid not null,id uuid not null,title text not null check(length(btrim(title)) between 1 and 160),position integer not null check(position between 0 and 999),primary key(owner_id,template_id,id),foreign key(owner_id,template_id) references public.pro_schedule_templates(owner_id,id) on delete cascade);
