create table if not exists public.pro_schedule_template_dependencies(owner_id uuid not null,template_id uuid not null,task_id uuid not null,predecessor_id uuid not null,primary key(owner_id,template_id,task_id,predecessor_id),foreign key(owner_id,template_id,task_id) references public.pro_schedule_template_tasks(owner_id,template_id,id) on delete cascade,foreign key(owner_id,template_id,predecessor_id) references public.pro_schedule_template_tasks(owner_id,template_id,id) on delete cascade,check(task_id<>predecessor_id));
create table if not exists public.pro_schedule_template_milestones(owner_id uuid not null,template_id uuid not null,id uuid not null,position integer not null check(position between 0 and 99),title text not null check(length(btrim(title)) between 1 and 160),offset_days integer not null check(offset_days between -80000 and 80000),notes text not null check(length(notes)<=1000),primary key(owner_id,template_id,id),unique(owner_id,template_id,position),foreign key(owner_id,template_id) references public.pro_schedule_templates(owner_id,id) on delete cascade);
