create or replace function public.pro_schedule_template_summary(p_template public.pro_schedule_templates) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_template.id,'name',p_template.name,'notes',p_template.notes,'revision',p_template.revision,'archived',p_template.archived,'phaseCount',(select count(*) from pro_schedule_template_phases where owner_id=p_template.owner_id and template_id=p_template.id),'taskCount',(select count(*) from pro_schedule_template_tasks where owner_id=p_template.owner_id and template_id=p_template.id),'milestoneCount',(select count(*) from pro_schedule_template_milestones where owner_id=p_template.owner_id and template_id=p_template.id));
$$;
create or replace function public.pro_schedule_template_detail(p_template public.pro_schedule_templates) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_schedule_template_summary(p_template)||jsonb_build_object(
 'phases',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'position',position) order by position,id) from pro_schedule_template_phases where owner_id=p_template.owner_id and template_id=p_template.id),'[]'::jsonb),
 'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'details',t.details,'assignee',t.assignee,'dueOffset',t.due_offset,'phaseId',t.phase_id,'startOffset',t.start_offset,'endOffset',t.end_offset,'dependsOn',coalesce((select jsonb_agg(d.predecessor_id order by d.predecessor_id) from pro_schedule_template_dependencies d where d.owner_id=t.owner_id and d.template_id=t.template_id and d.task_id=t.id),'[]'::jsonb)) order by t.position) from pro_schedule_template_tasks t where t.owner_id=p_template.owner_id and t.template_id=p_template.id),'[]'::jsonb),
 'milestones',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'offset',offset_days,'notes',notes) order by position) from pro_schedule_template_milestones where owner_id=p_template.owner_id and template_id=p_template.id),'[]'::jsonb));
$$;
create or replace function public.pro_schedule_templates_read(p_actor uuid,p_status text default 'active',p_query text default '',p_after uuid default null,p_template uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare t public.pro_schedule_templates;items jsonb;cursor_id uuid;needle text;want boolean;
begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_template is not null then select * into t from pro_schedule_templates where owner_id=p_actor and id=p_template;if not found then return null;end if;return jsonb_build_object('template',pro_schedule_template_detail(t));end if;
 if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 then raise exception 'Invalid query' using errcode='22023';end if;needle:=lower(btrim(p_query));want:=p_status='archived';
 if p_after is not null and not exists(select 1 from pro_schedule_templates where owner_id=p_actor and id=p_after and archived=want and(needle='' or position(needle in lower(name))>0 or position(needle in lower(notes))>0)) then raise exception 'Cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(pro_schedule_template_summary(x::public.pro_schedule_templates) order by x.id),'[]'::jsonb) into items from(select * from pro_schedule_templates where owner_id=p_actor and archived=want and(needle='' or position(needle in lower(name))>0 or position(needle in lower(notes))>0) and(p_after is null or id>p_after) order by id limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
-- Pure definition validator is also applied to server-captured snapshots.
create or replace function public.pro_schedule_template_validate(p_definition jsonb) returns void language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare r jsonb;d text;field text;keys text[];
begin
 if jsonb_typeof(p_definition->'phases') is distinct from 'array' or jsonb_typeof(p_definition->'tasks') is distinct from 'array' or jsonb_typeof(p_definition->'milestones') is distinct from 'array' then raise exception 'Invalid definition' using errcode='22023';end if;
 if jsonb_array_length(p_definition->'phases')>50 or jsonb_array_length(p_definition->'tasks')>100 or jsonb_array_length(p_definition->'milestones')>100 or jsonb_array_length(p_definition->'phases')+jsonb_array_length(p_definition->'tasks')+jsonb_array_length(p_definition->'milestones')=0 then raise exception 'Invalid definition capacity' using errcode='22023';end if;
 for d in select unnest(array['phases','tasks','milestones']) loop
  if (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(p_definition->d)) then raise exception 'Duplicate definition identity' using errcode='22023';end if;
  for r in select value from jsonb_array_elements(p_definition->d) loop
   if jsonb_typeof(r->'id') is distinct from 'string' then raise exception 'Invalid row identity' using errcode='22023';end if;perform (r->>'id')::uuid;
   if jsonb_typeof(r->'title') is distinct from 'string' or length(btrim(r->>'title')) not between 1 and 160 then raise exception 'Invalid title' using errcode='22023';end if;
   select array_agg(key order by key) into keys from jsonb_object_keys(r)key;
   if d='phases' then
    if keys is distinct from array['id','position','title'] or jsonb_typeof(r->'position') is distinct from 'number' or not coalesce((r->>'position')~'^[0-9]{1,3}$',false) then raise exception 'Invalid phase' using errcode='22023';end if;
   elsif d='milestones' then
    if keys is distinct from array['id','notes','offset','title'] or jsonb_typeof(r->'notes') is distinct from 'string' or length(r->>'notes')>1000 or jsonb_typeof(r->'offset') is distinct from 'number' or not coalesce((r->>'offset')~'^-?[0-9]{1,5}$',false) or abs((r->>'offset')::integer)>80000 then raise exception 'Invalid milestone' using errcode='22023';end if;
   else
    if keys is distinct from array['assignee','dependsOn','details','dueOffset','endOffset','id','phaseId','startOffset','title'] or jsonb_typeof(r->'details') is distinct from 'string' or length(r->>'details')>2000 or jsonb_typeof(r->'assignee') is distinct from 'string' or length(r->>'assignee')>160 or jsonb_typeof(r->'dependsOn') is distinct from 'array' or jsonb_array_length(r->'dependsOn')>5 then raise exception 'Invalid task' using errcode='22023';end if;
    if jsonb_typeof(r->'phaseId') is null or jsonb_typeof(r->'phaseId') not in('null','string') or r->>'phaseId' is not null and not exists(select 1 from jsonb_array_elements(p_definition->'phases')p where p->>'id'=r->>'phaseId') then raise exception 'Unknown phase' using errcode='22023';end if;
    for field in select unnest(array['dueOffset','startOffset','endOffset']) loop
     if jsonb_typeof(r->field) is null or jsonb_typeof(r->field) not in('null','number') or r->>field is not null and(not (r->>field)~'^-?[0-9]{1,5}$' or abs((r->>field)::integer)>80000) then raise exception 'Invalid date offset' using errcode='22023';end if;
    end loop;
    if (r->>'startOffset' is null)<>(r->>'endOffset' is null) or(r->>'startOffset')::integer>(r->>'endOffset')::integer then raise exception 'Invalid period' using errcode='22023';end if;
    if exists(select 1 from jsonb_array_elements(r->'dependsOn')x where jsonb_typeof(x) is distinct from 'string') then raise exception 'Invalid predecessor identity' using errcode='22023';end if;
    if exists(select 1 from jsonb_array_elements_text(r->'dependsOn')x where x=r->>'id' or not exists(select 1 from jsonb_array_elements(p_definition->'tasks')t where t->>'id'=x)) or (select count(*)<>count(distinct value) from jsonb_array_elements_text(r->'dependsOn')) then raise exception 'Unknown predecessor' using errcode='22023';end if;
   end if;
  end loop;
 end loop;
 if exists(with recursive edges as(select t->>'id' a,jsonb_array_elements_text(t->'dependsOn') b from jsonb_array_elements(p_definition->'tasks')t),reach(a,b) as(select a,b from edges union select r.a,e.b from reach r join edges e on e.a=r.b)select 1 from reach where a=b) then raise exception 'Cyclic plan' using errcode='22023';end if;
end $$;
create or replace function public.pro_schedule_template_day(p_start date,p_offset integer) returns text language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare result date;begin if p_offset is null then return null;end if;result:=p_start+p_offset;if result not between date'1900-01-01' and date'2100-12-31' then raise exception 'Date outside supported range' using errcode='22023';end if;return to_char(result,'YYYY-MM-DD');end $$;
create or replace function public.pro_schedule_template_preview(p_actor uuid,p_template uuid,p_work text,p_start text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare t public.pro_schedule_templates;definition jsonb;tasks jsonb:='[]'::jsonb;milestones jsonb:='[]'::jsonb;r jsonb;day date;cnt integer;pcnt integer;mcnt integer;head integer;last_position integer;target_phases jsonb;
begin
 perform pro_work_schedule_owner(p_actor,p_work);
 if exists(select 1 from pro_work where user_id=p_actor and id=p_work and coalesce(cancelled,false)) then raise exception 'Job cancelled' using errcode='40001';end if;
 if not coalesce(p_start~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid anchor' using errcode='22023';end if;day:=p_start::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid anchor' using errcode='22023';end if;
 select * into t from pro_schedule_templates where owner_id=p_actor and id=p_template;if not found then raise exception 'Forbidden' using errcode='42501';end if;if t.archived then raise exception 'Template archived' using errcode='40001';end if;
 definition:=pro_schedule_template_detail(t);
 select count(*) into cnt from pro_work_tasks where owner_id=p_actor and work_id=p_work;
 select count(*) into pcnt from pro_work_schedule_phases where owner_id=p_actor and work_id=p_work and not archived;
 select count(*) into mcnt from pro_work_schedule_milestones where owner_id=p_actor and work_id=p_work;
 if cnt+jsonb_array_length(definition->'tasks')>500 or pcnt+jsonb_array_length(definition->'phases')>50 or mcnt+jsonb_array_length(definition->'milestones')>500 or (select count(*) from pro_work_schedule_plans where owner_id=p_actor and work_id=p_work)+jsonb_array_length(definition->'tasks')>500 then raise exception 'Target capacity exceeded' using errcode='40001';end if;
 select coalesce(max(position),-1) into last_position from pro_work_schedule_phases where owner_id=p_actor and work_id=p_work;
 if last_position+jsonb_array_length(definition->'phases')>999 then raise exception 'Phase position capacity exceeded' using errcode='40001';end if;
 select coalesce(jsonb_agg(value||jsonb_build_object('position',last_position+ord) order by ord),'[]'::jsonb) into target_phases from jsonb_array_elements(definition->'phases')with ordinality x(value,ord);
 for r in select value from jsonb_array_elements(definition->'tasks') loop tasks:=tasks||jsonb_build_array(jsonb_build_object('id',r->'id','title',r->'title','details',r->'details','assignee',r->'assignee','dueDate',pro_schedule_template_day(day,(r->>'dueOffset')::integer),'phaseId',r->'phaseId','plannedStart',pro_schedule_template_day(day,(r->>'startOffset')::integer),'plannedEnd',pro_schedule_template_day(day,(r->>'endOffset')::integer),'dependsOn',r->'dependsOn'));end loop;
 for r in select value from jsonb_array_elements(definition->'milestones') loop milestones:=milestones||jsonb_build_array(jsonb_build_object('id',r->'id','title',r->'title','date',pro_schedule_template_day(day,(r->>'offset')::integer),'notes',r->'notes'));end loop;
 select revision into head from pro_work_schedule_heads where owner_id=p_actor and work_id=p_work;
 return jsonb_build_object('template',pro_schedule_template_summary(t),'workId',p_work,'startDate',p_start,'revision',coalesce(head,0),'existingCount',cnt,'existingPhaseCount',pcnt,'existingMilestoneCount',mcnt,'phases',target_phases,'tasks',tasks,'milestones',milestones);
end $$;
create or replace function public.pro_schedule_templates_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;template_key uuid;wid text;rev integer;head integer;expected_head integer;keys text[];allowed text[];t public.pro_schedule_templates;receipt public.pro_schedule_template_actions;definition jsonb;before_json jsonb;after_json jsonb;answer jsonb;preview jsonb;r jsonb;ref jsonb;task public.pro_work_tasks;plan public.pro_work_schedule_plans;phase public.pro_work_schedule_phases;milestone public.pro_work_schedule_milestones;day date;phases jsonb:='[]'::jsonb;tasks jsonb:='[]'::jsonb;milestones jsonb:='[]'::jsonb;deps jsonb;phase_map jsonb:='{}'::jsonb;task_map jsonb:='{}'::jsonb;selected_ids uuid[];new_phases uuid[];new_tasks uuid[];new_milestones uuid[];phase_actions uuid[];task_actions uuid[];plan_actions uuid[];milestone_actions uuid[];all_actions uuid[];child uuid;i integer;pos integer;includes_phases boolean;includes_deps boolean;includes_periods boolean;includes_details boolean;includes_manual boolean;includes_due boolean;includes_milestones boolean;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid operation' using errcode='22023';end if;act:=p_input->>'action';
 if act='save' then allowed:=array['action','actionId','milestones','name','notes','phases','revision','tasks','templateId'];
 elsif act='capture' then allowed:=array['action','actionId','anchorDate','includeDependencies','includeDetails','includeDueDates','includeManual','includeMilestones','includePeriods','includePhases','milestoneIds','name','notes','revision','selected','sourceRevision','sourceWorkId','templateId'];
 elsif act in('archive','restore') then allowed:=array['action','actionId','revision','templateId'];
 elsif act='apply' then allowed:=array['action','actionId','milestoneActionIds','milestoneIds','phaseActionIds','phaseIds','planActionIds','revision','startDate','taskActionIds','taskIds','templateId','workId','workRevision'];else raise exception 'Invalid action' using errcode='22023';end if;
 if exists(select 1 from jsonb_object_keys(p_input)k where not k=any(allowed)) or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'templateId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 0 and 2147483647 then raise exception 'Invalid identity' using errcode='22023';end if;
 if act in('save','archive','restore') and (select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from allowed then raise exception 'Missing fields' using errcode='22023';end if;
 if act='capture' and not p_input ?& array['action','actionId','anchorDate','milestoneIds','name','notes','revision','selected','sourceRevision','sourceWorkId','templateId'] then raise exception 'Missing capture fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;template_key:=(p_input->>'templateId')::uuid;rev:=(p_input->>'revision')::integer;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-schedule-template-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into receipt from pro_schedule_template_actions where actor_id=p_actor and action_id=aid;if found then if receipt.input is distinct from p_input then raise exception 'Operation identity reused' using errcode='22023';end if;return receipt.result;end if;
 if act='apply' then
  for keys in select array_agg(key order by key) from jsonb_object_keys(p_input)key loop if keys is distinct from allowed then raise exception 'Invalid apply fields' using errcode='22023';end if;end loop;
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 or not coalesce((p_input->>'workRevision')~'^[0-9]{1,10}$',false) or (p_input->>'workRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid target' using errcode='22023';end if;
  wid:=p_input->>'workId';expected_head:=(p_input->>'workRevision')::integer;

  for r in select jsonb_build_object('key',k) from unnest(array['phaseIds','phaseActionIds','taskIds','taskActionIds','planActionIds','milestoneIds','milestoneActionIds'])k loop
   if exists(select 1 from jsonb_array_elements(case when jsonb_typeof(p_input->(r->>'key'))='array' then p_input->(r->>'key') else '[]'::jsonb end)x where jsonb_typeof(x) is distinct from 'string') or jsonb_typeof(p_input->(r->>'key')) is distinct from 'array' or jsonb_array_length(p_input->(r->>'key'))>100 or (select count(*)<>count(distinct value) from jsonb_array_elements_text(p_input->(r->>'key'))) then raise exception 'Invalid child identities' using errcode='22023';end if;
  end loop;
  select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into new_phases from jsonb_array_elements_text(p_input->'phaseIds')with ordinality x(value,ord);select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into new_tasks from jsonb_array_elements_text(p_input->'taskIds')with ordinality x(value,ord);select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into new_milestones from jsonb_array_elements_text(p_input->'milestoneIds')with ordinality x(value,ord);
  select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into phase_actions from jsonb_array_elements_text(p_input->'phaseActionIds')with ordinality x(value,ord);select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into task_actions from jsonb_array_elements_text(p_input->'taskActionIds')with ordinality x(value,ord);select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into plan_actions from jsonb_array_elements_text(p_input->'planActionIds')with ordinality x(value,ord);select coalesce(array_agg(value::uuid order by ord),'{}'::uuid[]) into milestone_actions from jsonb_array_elements_text(p_input->'milestoneActionIds')with ordinality x(value,ord);
  all_actions:=phase_actions||task_actions||plan_actions||milestone_actions;
  if cardinality(all_actions)<>(select count(distinct a) from unnest(all_actions)a) or aid=any(all_actions) then raise exception 'Repeated action identities' using errcode='22023';end if;
  -- Acquire child action namespaces BEFORE the work lock: old writers use this order.
  for child in select unnest(task_actions) order by 1 loop perform pg_advisory_xact_lock(hashtextextended('pro-work-task-action:'||p_actor::text||':'||child::text,0));end loop;
  for child in select unnest(phase_actions||plan_actions||milestone_actions) order by 1 loop perform pg_advisory_xact_lock(hashtextextended('pro-work-schedule-action:'||p_actor::text||':'||child::text,0));end loop;
 elsif act='capture' then
  if jsonb_typeof(p_input->'sourceWorkId') is distinct from 'string' or length(p_input->>'sourceWorkId') not between 1 and 160 or not coalesce((p_input->>'sourceRevision')~'^[0-9]{1,10}$',false) or(p_input->>'sourceRevision')::numeric not between 0 and 2147483647 or rev<>0 or jsonb_typeof(p_input->'selected') is distinct from 'array' or jsonb_array_length(p_input->'selected')>100 or jsonb_typeof(p_input->'milestoneIds') is distinct from 'array' or jsonb_array_length(p_input->'milestoneIds')>100 then raise exception 'Invalid source' using errcode='22023';end if;
  wid:=p_input->>'sourceWorkId';expected_head:=(p_input->>'sourceRevision')::integer;
 end if;
