  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));perform 1 from pro_work where user_id=p_actor and id=wid for share;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select revision into head from pro_work_schedule_heads where owner_id=p_actor and work_id=wid for update;head:=coalesce(head,0);if head<>expected_head then raise exception 'Plan changed' using errcode='40001';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-schedule-template-definition:'||p_actor::text||':'||template_key::text,0));
 select * into t from pro_schedule_templates where owner_id=p_actor and id=template_key for update;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if found then
  if rev=0 or t.revision<>rev or act='capture' then raise exception 'Template changed' using errcode='40001';end if;before_json:=pro_schedule_template_detail(t);
  if t.archived and act not in('restore') or not t.archived and act='restore' then raise exception 'Template status changed' using errcode='40001';end if;
 elsif rev<>0 or act not in('save','capture') then raise exception 'Forbidden' using errcode='42501';end if;
 if act='apply' then
  preview:=pro_schedule_template_preview(p_actor,template_key,wid,p_input->>'startDate');definition:=pro_schedule_template_detail(t);
  if cardinality(new_phases)<>jsonb_array_length(preview->'phases') or cardinality(phase_actions)<>cardinality(new_phases) or cardinality(new_tasks)<>jsonb_array_length(preview->'tasks') or cardinality(task_actions)<>cardinality(new_tasks) or cardinality(plan_actions)<>cardinality(new_tasks) or cardinality(new_milestones)<>jsonb_array_length(preview->'milestones') or cardinality(milestone_actions)<>cardinality(new_milestones) then raise exception 'Definition changed' using errcode='40001';end if;
  if head::bigint+cardinality(new_phases)+cardinality(new_tasks)+cardinality(new_milestones)>2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;
  if exists(select 1 from pro_work_tasks where owner_id=p_actor and id=any(new_tasks)) or exists(select 1 from pro_work_schedule_phases where owner_id=p_actor and work_id=wid and id=any(new_phases)) or exists(select 1 from pro_work_schedule_milestones where owner_id=p_actor and work_id=wid and id=any(new_milestones)) or exists(select 1 from pro_work_task_actions where actor_id=p_actor and action_id=any(task_actions)) or exists(select 1 from pro_work_schedule_actions where actor_id=p_actor and action_id=any(phase_actions||plan_actions||milestone_actions)) then raise exception 'Child identity already used' using errcode='40001';end if;
  before_json:=jsonb_build_object('template',definition,'revision',head,'existingCount',preview->'existingCount','existingPhaseCount',preview->'existingPhaseCount','existingMilestoneCount',preview->'existingMilestoneCount');
  i:=0;for r in select value from jsonb_array_elements(preview->'phases') loop i:=i+1;phase_map:=phase_map||jsonb_build_object(r->>'id',new_phases[i]);end loop;
  i:=0;for r in select value from jsonb_array_elements(preview->'tasks') loop i:=i+1;task_map:=task_map||jsonb_build_object(r->>'id',new_tasks[i]);perform pro_work_tasks_mutate(p_actor,jsonb_build_object('action','create','actionId',task_actions[i],'workId',wid,'taskId',new_tasks[i],'revision',0,'title',r->'title','details',r->'details','assignee',r->'assignee','dueDate',r->'dueDate'));end loop;
  i:=0;for r in select value from jsonb_array_elements(preview->'phases') loop i:=i+1;perform pro_work_schedule_mutate(p_actor,jsonb_build_object('action','phase_save','actionId',phase_actions[i],'workId',wid,'revision',head,'phaseId',new_phases[i],'title',r->'title','position',r->'position'));head:=head+1;end loop;
  i:=0;for r in select value from jsonb_array_elements(preview->'tasks') loop i:=i+1;select coalesce(jsonb_agg(task_map->value),'[]'::jsonb) into deps from jsonb_array_elements_text(r->'dependsOn');perform pro_work_schedule_mutate(p_actor,jsonb_build_object('action','task_plan','actionId',plan_actions[i],'workId',wid,'revision',head,'taskId',new_tasks[i],'phaseId',phase_map->(r->>'phaseId'),'plannedStart',r->'plannedStart','plannedEnd',r->'plannedEnd','dependsOn',deps));head:=head+1;end loop;
  i:=0;for r in select value from jsonb_array_elements(preview->'milestones') loop i:=i+1;perform pro_work_milestones_mutate(p_actor,jsonb_build_object('action','milestone_save','actionId',milestone_actions[i],'workId',wid,'revision',head,'milestoneId',new_milestones[i],'title',r->'title','date',r->'date','notes',r->'notes'));head:=head+1;end loop;
  answer:=jsonb_build_object('action','apply','templateId',template_key,'templateRevision',t.revision,'workId',wid,'revision',head,'phaseIds',to_jsonb(new_phases),'taskIds',to_jsonb(new_tasks),'milestoneIds',to_jsonb(new_milestones));after_json:=answer;
 else
  if rev>=2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;
  if act in('save','capture') then
   if jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 80 or jsonb_typeof(p_input->'notes') is distinct from 'string' or length(p_input->>'notes')>1000 then raise exception 'Invalid name' using errcode='22023';end if;
   if act='save' then definition:=jsonb_build_object('phases',p_input->'phases','tasks',p_input->'tasks','milestones',p_input->'milestones');else
    if not coalesce((p_input->>'anchorDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid anchor' using errcode='22023';end if;day:=(p_input->>'anchorDate')::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid anchor' using errcode='22023';end if;
    foreach wid in array array['includePhases','includeDependencies','includePeriods','includeDetails','includeManual','includeDueDates','includeMilestones'] loop if p_input?wid and jsonb_typeof(p_input->wid) is distinct from 'boolean' then raise exception 'Invalid capture flag' using errcode='22023';end if;end loop;wid:=p_input->>'sourceWorkId';
    includes_phases:=coalesce((p_input->>'includePhases')::boolean,true);includes_deps:=coalesce((p_input->>'includeDependencies')::boolean,true);includes_periods:=coalesce((p_input->>'includePeriods')::boolean,true);includes_details:=coalesce((p_input->>'includeDetails')::boolean,false);includes_manual:=coalesce((p_input->>'includeManual')::boolean,false);includes_due:=coalesce((p_input->>'includeDueDates')::boolean,false);includes_milestones:=coalesce((p_input->>'includeMilestones')::boolean,true);
    select coalesce(array_agg((value->>'taskId')::uuid),'{}'::uuid[]) into selected_ids from jsonb_array_elements(p_input->'selected');if cardinality(selected_ids)<>(select count(distinct x) from unnest(selected_ids)x) then raise exception 'Duplicate source task' using errcode='22023';end if;
    if includes_phases then for phase in select * from pro_work_schedule_phases where owner_id=p_actor and work_id=wid and not archived order by position,id loop phases:=phases||jsonb_build_array(jsonb_build_object('id',phase.id,'title',phase.title,'position',phase.position));end loop;end if;
    for ref in select value from jsonb_array_elements(p_input->'selected') loop
     if (select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['revision','taskId'] or not coalesce((ref->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid source reference' using errcode='22023';end if;
     select * into task from pro_work_tasks where owner_id=p_actor and work_id=wid and id=(ref->>'taskId')::uuid and not archived for share;if not found or task.revision::numeric<>(ref->>'revision')::numeric then raise exception 'Source task changed' using errcode='40001';end if;
     select * into plan from pro_work_schedule_plans where owner_id=p_actor and work_id=wid and task_id=task.id;
     if includes_phases and plan.phase_id is not null and not exists(select 1 from pro_work_schedule_phases where owner_id=p_actor and work_id=wid and id=plan.phase_id and not archived) then raise exception 'Source phase archived' using errcode='40001';end if;
     deps:='[]'::jsonb;if includes_deps then
      if exists(select 1 from pro_work_schedule_dependencies d left join pro_work_tasks x on x.owner_id=d.owner_id and x.work_id=d.work_id and x.id=d.predecessor_id where d.owner_id=p_actor and d.work_id=wid and d.task_id=task.id and(not d.predecessor_id=any(selected_ids) or x.id is null or x.archived)) then raise exception 'Include all available predecessors or disable dependency copying' using errcode='40001';end if;
      select coalesce(jsonb_agg(predecessor_id order by predecessor_id),'[]'::jsonb) into deps from pro_work_schedule_dependencies where owner_id=p_actor and work_id=wid and task_id=task.id;
     end if;
     tasks:=tasks||jsonb_build_array(jsonb_build_object('id',task.id,'title',task.title,'details',case when includes_details then task.details else '' end,'assignee',case when includes_manual then task.assignee else '' end,'dueOffset',case when includes_due then task.due_date-day else null end,'phaseId',case when includes_phases then plan.phase_id else null end,'startOffset',case when includes_periods then plan.planned_start-day else null end,'endOffset',case when includes_periods then plan.planned_end-day else null end,'dependsOn',deps));
    end loop;
    if includes_milestones then
     if (select count(*)<>count(distinct value) from jsonb_array_elements_text(p_input->'milestoneIds')) then raise exception 'Duplicate milestone' using errcode='22023';end if;
     for ref in select value from jsonb_array_elements(p_input->'milestoneIds') loop select * into milestone from pro_work_schedule_milestones where owner_id=p_actor and work_id=wid and id=(ref#>>'{}')::uuid and not archived;if not found then raise exception 'Milestone changed' using errcode='40001';end if;milestones:=milestones||jsonb_build_array(jsonb_build_object('id',milestone.id,'title',milestone.title,'offset',milestone.milestone_date-day,'notes',case when includes_details then milestone.notes else '' end));end loop;
    end if;
    definition:=jsonb_build_object('phases',phases,'tasks',tasks,'milestones',milestones);
   end if;
   perform pro_schedule_template_validate(definition);
   insert into pro_schedule_templates(owner_id,id,name,notes,revision) values(p_actor,template_key,btrim(p_input->>'name'),btrim(p_input->>'notes'),rev+1) on conflict(owner_id,id) do update set name=excluded.name,notes=excluded.notes,revision=excluded.revision returning * into t;
   delete from pro_schedule_template_dependencies where owner_id=p_actor and template_id=template_key;delete from pro_schedule_template_tasks where owner_id=p_actor and template_id=template_key;delete from pro_schedule_template_phases where owner_id=p_actor and template_id=template_key;delete from pro_schedule_template_milestones where owner_id=p_actor and template_id=template_key;
   for r in select value from jsonb_array_elements(definition->'phases') loop insert into pro_schedule_template_phases values(p_actor,template_key,(r->>'id')::uuid,btrim(r->>'title'),(r->>'position')::integer);end loop;
   pos:=0;for r in select value from jsonb_array_elements(definition->'tasks') loop insert into pro_schedule_template_tasks values(p_actor,template_key,(r->>'id')::uuid,pos,btrim(r->>'title'),btrim(r->>'details'),btrim(r->>'assignee'),(r->>'dueOffset')::integer,(r->>'phaseId')::uuid,(r->>'startOffset')::integer,(r->>'endOffset')::integer);pos:=pos+1;end loop;
   for r in select value from jsonb_array_elements(definition->'tasks') loop insert into pro_schedule_template_dependencies select p_actor,template_key,(r->>'id')::uuid,value::uuid from jsonb_array_elements_text(r->'dependsOn');end loop;
   pos:=0;for r in select value from jsonb_array_elements(definition->'milestones') loop insert into pro_schedule_template_milestones values(p_actor,template_key,(r->>'id')::uuid,pos,btrim(r->>'title'),(r->>'offset')::integer,btrim(r->>'notes'));pos:=pos+1;end loop;
  else update pro_schedule_templates set archived=(act='archive'),revision=revision+1 where owner_id=p_actor and id=template_key returning * into t;end if;
  answer:=jsonb_build_object('action',act,'template',pro_schedule_template_summary(t));after_json:=pro_schedule_template_detail(t);
 end if;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_schedule_template_actions(actor_id,action_id,template_id,input,result,before_state,after_state) values(p_actor,aid,template_key,p_input,answer,before_json,after_json);return answer;
end $$;
create or replace function public.pro_schedule_template_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_schedule_template_actions;begin if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_schedule_template_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
do $$declare tab text;fn record;begin
 foreach tab in array array['pro_schedule_templates','pro_schedule_template_phases','pro_schedule_template_tasks','pro_schedule_template_dependencies','pro_schedule_template_milestones','pro_schedule_template_actions'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 for fn in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_schedule_template_summary','pro_schedule_template_detail','pro_schedule_templates_read','pro_schedule_template_validate','pro_schedule_template_day','pro_schedule_template_preview','pro_schedule_templates_mutate','pro_schedule_template_action_read') loop execute format('revoke all on function %s from public,anon,authenticated',fn.signature);execute format('grant execute on function %s to service_role',fn.signature);end loop;
end $$;
drop trigger if exists pro_schedule_template_actions_immutable on public.pro_schedule_template_actions;
create trigger pro_schedule_template_actions_immutable before update on public.pro_schedule_template_actions for each row execute function public.pro_team_append_only();
commit;

-- ===== company-files-local.sql =====
-- LOCAL PRO ONLY. Private owner library. No team grants, sends or public sharing.
-- Existing work-file tables/functions are consumed, never replaced or altered.
begin;
create table if not exists public.pro_company_folders(owner_id uuid not null references profiles(id) on delete cascade,id uuid not null,parent_id uuid,name text not null check(length(btrim(name)) between 1 and 80 and name!~'[[:cntrl:]/\\]'),revision integer not null check(revision>0),archived boolean not null default false,favorite boolean not null default false,primary key(owner_id,id),foreign key(owner_id,parent_id) references public.pro_company_folders(owner_id,id),check(parent_id is distinct from id));
create table if not exists public.pro_company_files(owner_id uuid not null references profiles(id) on delete cascade,id uuid not null,folder_id uuid,name text not null check(length(name) between 1 and 160),mime_type text not null check(mime_type in('image/jpeg','application/pdf')),size_bytes integer not null check(size_bytes between 1 and 20971520),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),object_path text not null unique,revision integer not null default 1 check(revision>0),ready boolean not null default false,archived boolean not null default false,favorite boolean not null default false,created_at timestamptz not null default now(),primary key(owner_id,id),foreign key(owner_id,folder_id) references public.pro_company_folders(owner_id,id),check(mime_type<>'image/jpeg' or size_bytes<=20971520),check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end));
create table if not exists public.pro_company_file_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),result jsonb,before_state jsonb,after_state jsonb,at timestamptz not null default now(),primary key(actor_id,action_id));
create table if not exists public.pro_company_file_copies(owner_id uuid not null,action_id uuid not null,source_file_id uuid not null,source_revision integer not null check(source_revision>0),source_snapshot jsonb not null,source_path text not null,work_id text not null,target_file_id uuid not null unique,primary key(owner_id,action_id),foreign key(owner_id,action_id) references pro_company_file_actions(actor_id,action_id) on delete cascade,foreign key(owner_id,source_file_id) references pro_company_files(owner_id,id) on delete cascade,foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade);
create index if not exists pro_company_folders_page on pro_company_folders(owner_id,parent_id,archived,id);
create index if not exists pro_company_files_page on pro_company_files(owner_id,folder_id,archived,id) where ready;
create or replace function public.pro_company_folder_json(p_folder public.pro_company_folders) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_folder.id,'parentId',p_folder.parent_id,'name',p_folder.name,'revision',p_folder.revision,'archived',p_folder.archived,'favorite',p_folder.favorite)$$;
create or replace function public.pro_company_file_json(p_file public.pro_company_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_file.id,'folderId',p_file.folder_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,'sha256',p_file.sha256,'revision',p_file.revision,'ready',p_file.ready,'archived',p_file.archived,'favorite',p_file.favorite,'createdAt',p_file.created_at)$$;
create or replace function public.pro_company_ancestors(p_actor uuid,p_folder uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb:='[]'::jsonb;f pro_company_folders;n integer:=0;seen uuid[]:='{}';begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 while p_folder is not null loop
  if p_folder=any(seen) or n>=5 then raise exception 'Folder tree invalid' using errcode='40001';end if;
  select * into f from pro_company_folders where owner_id=p_actor and id=p_folder and not archived;if not found then raise exception 'Folder unavailable' using errcode='40001';end if;
  result:=jsonb_build_array(pro_company_folder_json(f))||result;seen:=array_append(seen,p_folder);p_folder:=f.parent_id;n:=n+1;
 end loop;return result;
end $$;
create or replace function public.pro_company_files_read(p_actor uuid,p_scope text default 'folder',p_folder uuid default null,p_status text default 'active',p_query text default '',p_type text default 'all',p_starred boolean default false,p_after text default null,p_file uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f pro_company_files;items jsonb;ancestors jsonb:='[]'::jsonb;cursor_kind text;cursor_id uuid;next_cursor text;want boolean;needle text;
begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_file is not null then select * into f from pro_company_files where owner_id=p_actor and id=p_file and ready;if not found then return null;end if;return jsonb_build_object('file',pro_company_file_json(f),'ancestors',pro_company_ancestors(p_actor,f.folder_id));end if;
 if p_scope is null or p_scope not in('folder','all') or p_scope='all' and p_folder is not null or p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_type is null or p_type not in('all','image','pdf') or p_starred is null then raise exception 'Invalid library query' using errcode='22023';end if;
 if p_scope='folder' then ancestors:=pro_company_ancestors(p_actor,p_folder);end if;want:=p_status='archived';needle:=lower(btrim(p_query));
 if p_after is not null then if not p_after~'^(folder|file):[a-f0-9-]{36}$' then raise exception 'Invalid cursor' using errcode='22023';end if;cursor_kind:=split_part(p_after,':',1);cursor_id:=split_part(p_after,':',2)::uuid;end if;
 -- Both branches have a single current-owner predicate before keyset filtering.
 with candidates as(
  select 'folder'::text kind,d.id,pro_company_folder_json(d) data from pro_company_folders d where d.owner_id=p_actor and d.archived=want and(p_scope='all' or d.parent_id is not distinct from p_folder) and p_type='all' and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)
  union all select 'file',d.id,pro_company_file_json(d) from pro_company_files d where d.owner_id=p_actor and d.ready and d.archived=want and(p_scope='all' or d.folder_id is not distinct from p_folder) and(p_type='all' or p_type='image' and d.mime_type='image/jpeg' or p_type='pdf' and d.mime_type='application/pdf') and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)
 ),eligible as(select *,case kind when 'folder' then 0 else 1 end sort from candidates),paged as(select * from eligible where p_after is null or(sort,id)>(case cursor_kind when 'folder' then 0 else 1 end,cursor_id) order by sort,id limit 21)
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,kind,data) order by sort,id),'[]'::jsonb) into items from paged;
 if p_after is not null then
  if cursor_kind='folder' then
   if not exists(select 1 from pro_company_folders d where d.owner_id=p_actor and d.id=cursor_id and d.archived=want and(p_scope='all' or d.parent_id is not distinct from p_folder) and p_type='all' and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)) then raise exception 'Cursor changed' using errcode='40001';end if;
  elsif not exists(select 1 from pro_company_files d where d.owner_id=p_actor and d.id=cursor_id and d.ready and d.archived=want and(p_scope='all' or d.folder_id is not distinct from p_folder) and(p_type='all' or p_type='image' and d.mime_type='image/jpeg' or p_type='pdf' and d.mime_type='application/pdf') and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)) then raise exception 'Cursor changed' using errcode='40001';end if;
 end if;
 if jsonb_array_length(items)>20 then next_cursor:=items->19->>'kind';next_cursor:=next_cursor||':'||(items->19->next_cursor->>'id');items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',next_cursor,'ancestors',ancestors);
end $$;
create or replace function public.pro_company_file_download(p_actor uuid,p_file uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f pro_company_files;begin if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into f from pro_company_files where owner_id=p_actor and id=p_file and ready;if not found then return null;end if;perform pro_company_ancestors(p_actor,f.folder_id);return jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);end $$;
-- The reservation is private server state; public proof never exposes storage paths.
create or replace function public.pro_company_action_state(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_company_file_actions;f pro_company_files;c pro_company_file_copies;target jsonb;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_company_file_actions where actor_id=p_actor and action_id=p_action;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 if r.result is not null then return jsonb_build_object('result',r.result);end if;
 if r.input->>'action'='upload' then select * into f from pro_company_files where owner_id=p_actor and id=(r.input->>'fileId')::uuid;if not found then raise exception 'Reservation missing' using errcode='42501';end if;return jsonb_build_object('result',null,'upload',jsonb_build_object('file',pro_company_file_json(f),'objectPath',f.object_path));
 elsif r.input->>'action'='copy' then
  select * into c from pro_company_file_copies where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
  perform 1 from pro_work where user_id=p_actor and id=c.work_id;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select jsonb_build_object('objectPath',object_path,'file',pro_work_file_json(w)) into target from pro_work_files w where owner_id=p_actor and id=c.target_file_id and work_id=c.work_id;if target is null then raise exception 'Target missing' using errcode='42501';end if;
  return jsonb_build_object('result',null,'copy',jsonb_build_object('sourcePath',c.source_path,'source',c.source_snapshot,'target',target));
 else raise exception 'Invalid pending action' using errcode='22023';end if;
end $$;
create or replace function public.pro_company_files_mutate(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;fid uuid;parent uuid;rev integer;keys text[];expected text[];r pro_company_file_actions;f pro_company_files;folder pro_company_folders;before_json jsonb;answer jsonb;ancestors jsonb;max_depth integer;target uuid;wid text;snapshot jsonb;reserved jsonb;bytes integer;mime text;canonical_name text;
begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;
 case act
 when 'folder_save' then expected:=array['action','actionId','favorite','folderId','name','parentId','revision'];
 when 'folder_archive','folder_restore' then expected:=array['action','actionId','folderId','revision'];
 when 'file_update' then expected:=array['action','actionId','favorite','fileId','folderId','name','revision'];
 when 'file_archive','file_restore' then expected:=array['action','actionId','fileId','revision'];
 when 'upload' then expected:=array['action','actionId','fileId','folderId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName'];
 when 'copy' then expected:=array['action','actionId','fileId','revision','targetFileId','workId'];
 else raise exception 'Invalid action' using errcode='22023';end case;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected then raise exception 'Invalid action fields' using errcode='22023';end if;
 if act<>'upload' and(jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483647) then raise exception 'Invalid revision' using errcode='22023';end if;
 if act<>'upload' then rev:=(p_input->>'revision')::integer;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-file-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_company_file_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Operation identity reused' using errcode='22023';end if;return pro_company_action_state(p_actor,aid);end if;
 if act='copy' then if jsonb_typeof(p_input->'targetFileId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' then raise exception 'Invalid copy identity' using errcode='22023';end if;target:=(p_input->>'targetFileId')::uuid;perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||target::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if act like 'folder_%' then
  if jsonb_typeof(p_input->'folderId') is distinct from 'string' then raise exception 'Invalid folder identity' using errcode='22023';end if;fid:=(p_input->>'folderId')::uuid;
  select * into folder from pro_company_folders where owner_id=p_actor and id=fid for update;
  if found then if rev<>folder.revision or rev=0 then raise exception 'Folder changed' using errcode='40001';end if;before_json:=pro_company_folder_json(folder);
  elsif act<>'folder_save' or rev<>0 then raise exception 'Folder missing' using errcode='42501';end if;
  if rev>=2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;
  if act='folder_save' then
   if folder.archived or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 80 or(p_input->>'name')~'[[:cntrl:]/\\]' or jsonb_typeof(p_input->'favorite') is distinct from 'boolean' or jsonb_typeof(p_input->'parentId') is null or jsonb_typeof(p_input->'parentId') not in('string','null') then raise exception 'Invalid folder' using errcode='22023';end if;
   parent:=(p_input->>'parentId')::uuid;ancestors:=pro_company_ancestors(p_actor,parent);
   if fid=parent or exists(select 1 from jsonb_array_elements(ancestors)x where x->>'id'=fid::text) then raise exception 'Folder cycle' using errcode='40001';end if;
   with recursive subtree(id,depth) as(select fid,1 union all select d.id,s.depth+1 from pro_company_folders d join subtree s on d.parent_id=s.id where d.owner_id=p_actor)select max(depth) into max_depth from subtree;
   if jsonb_array_length(ancestors)+max_depth>5 then raise exception 'Folder depth exceeds five' using errcode='40001';end if;
   if rev=0 and(select count(*) from pro_company_folders where owner_id=p_actor)>=100 then raise exception 'Folder capacity exceeded' using errcode='40001';end if;
   insert into pro_company_folders(owner_id,id,parent_id,name,revision,favorite) values(p_actor,fid,parent,btrim(p_input->>'name'),rev+1,(p_input->>'favorite')::boolean) on conflict(owner_id,id) do update set parent_id=excluded.parent_id,name=excluded.name,revision=excluded.revision,favorite=excluded.favorite returning * into folder;
  else
   if folder.archived=(act='folder_archive') then raise exception 'Folder status changed' using errcode='40001';end if;
   if act='folder_archive' and(exists(select 1 from pro_company_folders where owner_id=p_actor and parent_id=fid) or exists(select 1 from pro_company_files where owner_id=p_actor and folder_id=fid)) then raise exception 'Move the folder contents before archiving' using errcode='40001';end if;
   perform pro_company_ancestors(p_actor,folder.parent_id);update pro_company_folders set archived=(act='folder_archive'),revision=revision+1 where owner_id=p_actor and id=fid returning * into folder;
  end if;answer:=jsonb_build_object('action',act,'folder',pro_company_folder_json(folder));
 elsif act='upload' then
  if jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'folderId') is null or jsonb_typeof(p_input->'folderId') not in('null','string') or jsonb_typeof(p_input->'sourceName') is distinct from 'string' or length(p_input->>'sourceName') not between 1 and 160 or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or p_input->>'mimeType' not in('image/jpeg','application/pdf') then raise exception 'Invalid file reservation' using errcode='22023';end if;
  fid:=(p_input->>'fileId')::uuid;parent:=(p_input->>'folderId')::uuid;perform pro_company_ancestors(p_actor,parent);
  if exists(select 1 from pro_company_files where owner_id=p_actor and id=fid) then raise exception 'File identity already used' using errcode='40001';end if;
  if(select count(*) from pro_company_files where owner_id=p_actor)>=500 then raise exception 'File capacity exceeded' using errcode='40001';end if;
  mime:=p_input->>'mimeType';bytes:=(p_input->>'sizeBytes')::integer;canonical_name:=p_input->>'name';
  if bytes not between 1 and 20971520 or mime='image/jpeg' and bytes>20971520 or length(canonical_name) not between 1 and 160 or canonical_name~'[[:cntrl:]/\\]' or mime='application/pdf' and right(canonical_name,4)<>'.pdf' or mime='image/jpeg' and right(canonical_name,4)<>'.jpg' then raise exception 'Invalid canonical file' using errcode='22023';end if;
  insert into pro_company_files(owner_id,id,folder_id,name,mime_type,size_bytes,sha256,object_path) values(p_actor,fid,parent,canonical_name,mime,bytes,p_input->>'sha256',p_actor::text||'/'||fid::text||case when mime='application/pdf' then '.pdf' else '.jpg' end) returning * into f;
 elsif act='copy' then
  fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160 then raise exception 'Invalid work' using errcode='22023';end if;
  select * into f from pro_company_files where owner_id=p_actor and id=fid and ready and not archived for share;if not found then raise exception 'Source unavailable' using errcode='42501';end if;if f.revision<>rev then raise exception 'Source changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);
  perform pg_advisory_xact_lock(hashtextextended('pro-work-files:'||p_actor::text||':'||wid,0));
  perform 1 from pro_work where user_id=p_actor and id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if exists(select 1 from pro_work where user_id=p_actor and id=wid and coalesce(cancelled,false)) then raise exception 'Work cancelled' using errcode='40001';end if;
  if exists(select 1 from pro_work_files where id=target) or exists(select 1 from pro_work_file_upload_actions where actor_id=p_actor and file_id=target) then raise exception 'Target identity used' using errcode='40001';end if;
  if(select count(*) from pro_work_files where owner_id=p_actor and work_id=wid)>=100 then raise exception 'Work files capacity exceeded' using errcode='40001';end if;
  snapshot:=pro_company_file_json(f);reserved:=pro_work_file_reserve(p_actor,jsonb_build_object('fileId',target,'workId',wid,'sourceName',f.name,'name',f.name,'mimeType',f.mime_type,'rawSha256',f.sha256,'sha256',f.sha256,'sizeBytes',f.size_bytes));
 else
  fid:=(p_input->>'fileId')::uuid;select * into f from pro_company_files where owner_id=p_actor and id=fid and ready for update;if not found then raise exception 'File missing' using errcode='42501';end if;if rev<>f.revision then raise exception 'File changed' using errcode='40001';end if;if rev>=2147483647 then raise exception 'Revision exhausted' using errcode='40001';end if;before_json:=pro_company_file_json(f);
  if act='file_update' then
   if f.archived then raise exception 'File archived' using errcode='40001';end if;
   if jsonb_typeof(p_input->'folderId') is null or jsonb_typeof(p_input->'folderId') not in('null','string') or jsonb_typeof(p_input->'favorite') is distinct from 'boolean' or jsonb_typeof(p_input->'name') is distinct from 'string' then raise exception 'Invalid file metadata' using errcode='22023';end if;
   parent:=(p_input->>'folderId')::uuid;perform pro_company_ancestors(p_actor,parent);canonical_name:=p_input->>'name';if length(canonical_name) not between 1 and 160 or canonical_name~'[[:cntrl:]/\\]' or f.mime_type='application/pdf' and right(canonical_name,4)<>'.pdf' or f.mime_type='image/jpeg' and right(canonical_name,4)<>'.jpg' then raise exception 'Invalid file name' using errcode='22023';end if;
   update pro_company_files set name=canonical_name,folder_id=parent,favorite=(p_input->>'favorite')::boolean,revision=revision+1 where owner_id=p_actor and id=fid returning * into f;
  else
   if f.archived=(act='file_archive') then raise exception 'File status changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);update pro_company_files set archived=(act='file_archive'),revision=revision+1 where owner_id=p_actor and id=fid returning * into f;
  end if;answer:=jsonb_build_object('action',act,'file',pro_company_file_json(f));
 end if;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_company_file_actions(actor_id,action_id,input,input_hash,result,before_state,after_state) values(p_actor,aid,p_input,p_input_hash,answer,before_json,case when answer is null then null else answer end);
 if act='copy' then insert into pro_company_file_copies(owner_id,action_id,source_file_id,source_revision,source_snapshot,source_path,work_id,target_file_id) values(p_actor,aid,fid,f.revision,snapshot,f.object_path,wid,target);end if;
 return pro_company_action_state(p_actor,aid);
end $$;
create or replace function public.pro_company_file_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_company_file_actions;f pro_company_files;c pro_company_file_copies;answer jsonb;work_ack jsonb;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-file-action:'||p_actor::text||':'||p_action::text,0));
 select * into r from pro_company_file_actions where actor_id=p_actor and action_id=p_action for update;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 if r.result is not null then return r.result;end if;
 if r.input->>'action'='copy' then select * into c from pro_company_file_copies where owner_id=p_actor and action_id=p_action;perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||c.target_file_id::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if r.input->>'action'='upload' then
  select * into f from pro_company_files where owner_id=p_actor and id=(r.input->>'fileId')::uuid for update;if not found then raise exception 'File missing' using errcode='42501';end if;perform pro_company_ancestors(p_actor,f.folder_id);
  update pro_company_files set ready=true where owner_id=p_actor and id=f.id returning * into f;answer:=jsonb_build_object('action','upload','file',pro_company_file_json(f));
 elsif r.input->>'action'='copy' then
  if not exists(select 1 from pro_work where user_id=p_actor and id=c.work_id) then raise exception 'Forbidden' using errcode='42501';end if;
  work_ack:=pro_work_file_ready(p_actor,c.target_file_id,c.source_snapshot->>'sha256');answer:=jsonb_build_object('action','copy','copy',jsonb_build_object('sourceFileId',c.source_file_id,'sourceRevision',c.source_revision,'workId',c.work_id,'file',work_ack->'file'));
 else raise exception 'Not a pending upload' using errcode='22023';end if;
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 update pro_company_file_actions set result=answer,after_state=answer where actor_id=p_actor and action_id=p_action;return answer;
end $$;
create or replace function public.pro_company_file_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_company_file_actions;begin if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_company_file_actions where actor_id=p_actor and action_id=p_action;if not found or r.result is null then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'result',r.result));end $$;
create or replace function public.pro_company_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if (to_jsonb(new)-array['folder_id','name','revision','ready','archived','favorite']) is distinct from(to_jsonb(old)-array['folder_id','name','revision','ready','archived','favorite']) then raise exception 'File bytes immutable' using errcode='23514';end if;
 if not old.ready then if not new.ready or(to_jsonb(new)-'ready') is distinct from(to_jsonb(old)-'ready') then raise exception 'Only readiness transition allowed' using errcode='23514';end if;
 elsif not new.ready or new.revision<>old.revision+1 then raise exception 'Metadata needs next revision' using errcode='23514';end if;return new;end $$;
create or replace function public.pro_company_file_action_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.result is not null or new.result is null or(to_jsonb(new)-array['result','after_state']) is distinct from(to_jsonb(old)-array['result','after_state']) then raise exception 'Receipt immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_company_file_immutable on pro_company_files;create trigger pro_company_file_immutable before update on pro_company_files for each row execute function pro_company_file_immutable();
drop trigger if exists pro_company_file_action_immutable on pro_company_file_actions;create trigger pro_company_file_action_immutable before update on pro_company_file_actions for each row execute function pro_company_file_action_immutable();
drop trigger if exists pro_company_file_copies_immutable on pro_company_file_copies;create trigger pro_company_file_copies_immutable before update on pro_company_file_copies for each row execute function pro_team_append_only();
do $$declare tab text;fn record;begin foreach tab in array array['pro_company_folders','pro_company_files','pro_company_file_actions','pro_company_file_copies'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 for fn in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_company_folder_json','pro_company_file_json','pro_company_ancestors','pro_company_files_read','pro_company_file_download','pro_company_action_state','pro_company_files_mutate','pro_company_file_ready','pro_company_file_action_read','pro_company_file_immutable','pro_company_file_action_immutable') loop execute format('revoke all on function %s from public,anon,authenticated',fn.signature);execute format('grant execute on function %s to service_role',fn.signature);end loop;
end $$;
do $$begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-company-files','pro-company-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-company-files' and not public and file_size_limit=20971520 and allowed_mime_types @> array['image/jpeg','application/pdf'] /* Ronda F2-D: file-formats-library-local.sql widens the list */) then raise exception 'Company bucket private configuration mismatch';end if;
 end if;
 if to_regclass('storage.objects') is not null then execute 'drop policy if exists pro_company_files_no_direct on storage.objects';execute 'create policy pro_company_files_no_direct on storage.objects as restrictive for all to anon,authenticated using(bucket_id <> ''pro-company-files'') with check(bucket_id <> ''pro-company-files'')';end if;
end $$;
commit;

-- ===== daily-logs-local.sql =====
-- LOCAL PRO ONLY. Structured daily logs alongside existing text advances.
-- No existing function/table replacement, notifications, costs, contacts or sends.
begin;
create table if not exists public.pro_daily_log_defaults(owner_id uuid primary key references profiles(id) on delete cascade,revision integer not null check(revision>0),summary text not null check(length(summary)<=2000),sections jsonb not null);
create table if not exists public.pro_daily_logs(owner_id uuid not null,work_id text not null,id uuid not null,log_date date not null check(log_date between date'1900-01-01' and date'2100-12-31'),title text not null check(length(btrim(title)) between 1 and 160),summary text not null check(length(summary)<=2000),sections jsonb not null,weather jsonb,snapshot jsonb not null,revision integer not null check(revision>0),created_by uuid not null,created_by_name text not null check(length(created_by_name)<=160),created_grant_id uuid,source_invite_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_revision integer,archived boolean not null default false,primary key(owner_id,work_id,id),foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade,check((created_grant_id is null)=(source_invite_id is null)),check(published_revision is null or published_revision between 1 and revision));
create table if not exists public.pro_daily_log_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null references profiles(id) on delete cascade,work_id text,grant_id uuid,source_invite_id uuid,input jsonb not null,result jsonb not null,before_state jsonb,after_state jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id));
create table if not exists public.pro_daily_log_history(owner_id uuid not null,work_id text not null,log_id uuid not null,action_id uuid not null,actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),action text not null check(action in('create','update','duplicate','archive','restore','publish')),before_log jsonb,after_log jsonb not null,at timestamptz not null default now(),primary key(owner_id,work_id,log_id,action_id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_versions(owner_id uuid not null,work_id text not null,log_id uuid not null,version integer not null check(version>0),log_revision integer not null check(log_revision>0),content jsonb not null,primary key(owner_id,work_id,log_id,version),unique(owner_id,work_id,log_id,log_revision),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_audiences(owner_id uuid not null,work_id text not null,log_id uuid not null,version integer not null,kind text not null check(kind in('client','team')),recipient_id uuid not null,request_id uuid,grant_id uuid,source_invite_id uuid,primary key(owner_id,work_id,log_id,version,kind,recipient_id),foreign key(owner_id,work_id,log_id,version) references pro_daily_log_versions(owner_id,work_id,log_id,version) on delete cascade,check(kind='client' and request_id is not null and grant_id is null and source_invite_id is null or kind='team' and request_id is null and grant_id is not null and source_invite_id is not null));
create index if not exists pro_daily_logs_page on pro_daily_logs(owner_id,work_id,archived,id);
create index if not exists pro_daily_log_audiences_actor on pro_daily_log_audiences(recipient_id,owner_id,work_id,log_id,version desc);
create or replace function public.pro_daily_log_context(p_actor uuid,p_work text,p_grant uuid default null,p_write boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g pro_team_grants;begin
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid scope' using errcode='22023';end if;
 if p_grant is null then perform pro_work_schedule_owner(p_actor,p_work);return jsonb_build_object('ownerId',p_actor,'isOwner',true,'grantId',null,'sourceInviteId',null,'role','owner');end if;
 g:=pro_team_context(p_actor,p_grant,p_write);if p_actor=g.owner_id then raise exception 'Owners use a private work scope' using errcode='22023';end if;if g.work_id<>p_work then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('ownerId',g.owner_id,'isOwner',p_actor=g.owner_id,'grantId',case when p_actor=g.owner_id then null else g.id end,'sourceInviteId',case when p_actor=g.owner_id then null else g.source_invite_id end,'role',case when p_actor=g.owner_id then 'owner' else g.role end);
end $$;
create or replace function public.pro_daily_log_json(p_log public.pro_daily_logs) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_log.id,'ownerId',p_log.owner_id,'workId',p_log.work_id,'date',to_char(p_log.log_date,'YYYY-MM-DD'),'title',p_log.title,'summary',p_log.summary,'sections',p_log.sections,'weather',p_log.weather,'snapshot',p_log.snapshot,'revision',p_log.revision,'createdBy',p_log.created_by,'createdByName',p_log.created_by_name,'createdGrantId',p_log.created_grant_id,'sourceInviteId',p_log.source_invite_id,'createdAt',p_log.created_at,'updatedAt',p_log.updated_at,'publishedRevision',p_log.published_revision,'archived',p_log.archived)$$;
create or replace function public.pro_daily_log_visible(p_actor uuid,p_context jsonb,p_log public.pro_daily_logs) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$select (p_context->>'isOwner')::boolean or p_log.created_by=p_actor and p_log.published_revision is null and p_log.created_grant_id=(p_context->>'grantId')::uuid and p_log.source_invite_id=(p_context->>'sourceInviteId')::uuid and p_context->>'role'='contributor'$$;
create or replace function public.pro_daily_log_sections_valid(p_sections jsonb) returns boolean language sql immutable security invoker set search_path=public,pg_temp as $$select coalesce(jsonb_typeof(p_sections)='object' and (select array_agg(key order by key) from jsonb_object_keys(p_sections)key)=array['plan','tasks','time','weather'] and not exists(select 1 from jsonb_each(p_sections)e where jsonb_typeof(e.value)<>'boolean'),false)$$;
create or replace function public.pro_daily_log_snapshot(p_actor uuid,p_work text,p_grant uuid,p_date text,p_tasks uuid[] default '{}',p_plan uuid[] default '{}',p_time boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;day date;result jsonb;begin
 ctx:=pro_daily_log_context(p_actor,p_work,p_grant,true);own:=(ctx->>'ownerId')::uuid;
 if p_tasks is null or p_plan is null or p_time is null or cardinality(p_tasks)>100 or cardinality(p_plan)>100 or array_position(p_tasks,null) is not null or array_position(p_plan,null) is not null or cardinality(p_tasks)<>(select count(distinct x) from unnest(p_tasks)x) or cardinality(p_plan)<>(select count(distinct x) from unnest(p_plan)x) or not coalesce(p_date~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid source selection' using errcode='22023';end if;
 day:=p_date::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid date' using errcode='22023';end if;
 -- One statement takes every source projection and effective-time aggregate from
 -- one MVCC snapshot. No details, assignee, rates, costs or private notes selected.
 with selected_tasks as(select t.id,t.title,t.status,t.due_date,t.revision from pro_work_tasks t where t.owner_id=own and t.work_id=p_work and not t.archived and t.id=any(p_tasks)),selected_plans as(select t.id,t.title,t.revision,p.phase_id,p.planned_start,p.planned_end,case when not f.archived then f.title else null end phase_title from pro_work_tasks t join pro_work_schedule_plans p on p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id left join pro_work_schedule_phases f on f.owner_id=p.owner_id and f.work_id=p.work_id and f.id=p.phase_id where t.owner_id=own and t.work_id=p_work and not t.archived and t.id=any(p_plan)),data as(select jsonb_build_object('date',p_date,'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'status',status,'dueDate',case when due_date is null then null else to_char(due_date,'YYYY-MM-DD') end,'revision',revision) order by id) from selected_tasks),'[]'::jsonb),'plan',coalesce((select jsonb_agg(jsonb_build_object('taskId',s.id,'title',s.title,'phaseId',s.phase_id,'phaseTitle',s.phase_title,'plannedStart',case when s.planned_start is null then null else to_char(s.planned_start,'YYYY-MM-DD') end,'plannedEnd',case when s.planned_end is null then null else to_char(s.planned_end,'YYYY-MM-DD') end,'dependsOn',coalesce((select jsonb_agg(jsonb_build_object('taskId',d.predecessor_id,'title',case when not x.archived then x.title else null end,'status',case when not x.archived then x.status else null end,'available',x.id is not null and not x.archived) order by d.predecessor_id) from pro_work_schedule_dependencies d left join pro_work_tasks x on x.owner_id=d.owner_id and x.work_id=d.work_id and x.id=d.predecessor_id where d.owner_id=own and d.work_id=p_work and d.task_id=s.id),'[]'::jsonb)) order by s.id) from selected_plans s),'[]'::jsonb),'minutes',case when p_time then (select coalesce(sum(e.minutes),0) from pro_work_cost_entries e where e.user_id=own and e.work_id=p_work and e.recorded_on=day and e.kind='time' and not exists(select 1 from pro_work_cost_entries v where v.user_id=e.user_id and v.reversal_id=e.id)) else null end) value)
 select value||jsonb_build_object('fingerprint',md5(own::text||':'||length(p_work)::text||':'||p_work||':'||coalesce(ctx->>'grantId','owner')||':'||coalesce(ctx->>'sourceInviteId','owner')||':'||value::text)) into result from data;
 if jsonb_array_length(result->'tasks')<>cardinality(p_tasks) or jsonb_array_length(result->'plan')<>cardinality(p_plan) then raise exception 'Source selection changed' using errcode='40001';end if;return result;
end $$;
create or replace function public.pro_daily_log_options(p_actor uuid,p_work text,p_grant uuid,p_kind text,p_query text default '',p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;items jsonb;cursor_id uuid;needle text;begin ctx:=pro_daily_log_context(p_actor,p_work,p_grant,true);own:=(ctx->>'ownerId')::uuid;if p_kind is null or p_kind not in('tasks','plan') or p_query is null or length(p_query)>100 then raise exception 'Invalid options query' using errcode='22023';end if;needle:=lower(btrim(p_query));
 if p_after is not null and not exists(select 1 from pro_work_tasks t where t.owner_id=own and t.work_id=p_work and t.id=p_after and not t.archived and(needle='' or position(needle in lower(t.title))>0) and(p_kind='tasks' or exists(select 1 from pro_work_schedule_plans p where p.owner_id=own and p.work_id=p_work and p.task_id=t.id))) then raise exception 'Cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title) order by id),'[]'::jsonb) into items from(select t.id,t.title from pro_work_tasks t where t.owner_id=own and t.work_id=p_work and not t.archived and(p_after is null or t.id>p_after) and(needle='' or position(needle in lower(t.title))>0) and(p_kind='tasks' or exists(select 1 from pro_work_schedule_plans p where p.owner_id=own and p.work_id=p_work and p.task_id=t.id)) order by t.id limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_log_defaults_read(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_defaults;begin if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into d from pro_daily_log_defaults where owner_id=p_actor;if not found then return jsonb_build_object('revision',0,'summary','','sections',jsonb_build_object('weather',false,'plan',false,'tasks',false,'time',false));end if;return jsonb_build_object('revision',d.revision,'summary',d.summary,'sections',d.sections);end $$;
create or replace function public.pro_daily_logs_read(p_actor uuid,p_work text,p_grant uuid default null,p_status text default 'active',p_after uuid default null,p_log uuid default null,p_preview boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;is_owner boolean;items jsonb;cursor_id uuid;cursor_day date;cursor_created timestamptz;l pro_daily_logs;hist jsonb;r pro_appointment_requests;content jsonb;team jsonb;begin
 ctx:=pro_daily_log_context(p_actor,p_work,p_grant,false);own:=(ctx->>'ownerId')::uuid;is_owner:=(ctx->>'isOwner')::boolean;
 if p_log is not null then
  select * into l from pro_daily_logs where owner_id=own and work_id=p_work and id=p_log;if not found or not pro_daily_log_visible(p_actor,ctx,l) then return null;end if;
  if is_owner then select ar.* into r from pro_appointment_requests ar join profiles p on p.id=ar.client_user_id and not coalesce(p.is_disabled,false) join pro_work w on w.user_id=ar.owner_id and w.id=ar.work_id where ar.owner_id=own and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(w.cancelled,false) order by ar.id limit 1;end if;
  if p_preview then
   select jsonb_build_object('id',l.id,'date',to_char(l.log_date,'YYYY-MM-DD'),'title',l.title,'summary',l.summary,'sections',l.sections,'weather',l.weather,'snapshot',l.snapshot,'service',w.service,'authorName',l.created_by_name) into content from pro_work w where w.user_id=own and w.id=p_work;
   team:='[]'::jsonb;
   return jsonb_build_object('logId',l.id,'revision',l.revision,'content',content,'requestId',r.id,'recipientId',r.client_user_id,'recipientName',r.client_name,'team',team);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'actorId',h.actor_id,'actorName',h.actor_name,'action',h.action,'at',h.at,'before',h.before_log,'after',h.after_log) order by(h.after_log->>'revision')::integer desc),'[]'::jsonb) into hist from(select * from pro_daily_log_history where owner_id=own and work_id=p_work and log_id=p_log order by(after_log->>'revision')::integer desc limit 20)h;
  return jsonb_build_object('log',pro_daily_log_json(l),'history',hist,'canEdit',not l.archived,'canPublish',is_owner and not l.archived,'requestId',r.id,'recipientId',r.client_user_id,'recipientName',r.client_name);
 end if;
 if p_status is null or p_status not in('active','archived') then raise exception 'Invalid status' using errcode='22023';end if;
 if p_after is not null then select x.log_date,x.created_at into cursor_day,cursor_created from pro_daily_logs x where x.owner_id=own and x.work_id=p_work and x.id=p_after and x.archived=(p_status='archived') and pro_daily_log_visible(p_actor,ctx,x);if not found then raise exception 'Cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(pro_daily_log_json(x::public.pro_daily_logs) order by x.log_date desc,x.created_at desc,x.id desc),'[]'::jsonb) into items from(select * from pro_daily_logs x where x.owner_id=own and x.work_id=p_work and x.archived=(p_status='archived') and(p_after is null or(x.log_date,x.created_at,x.id)<(cursor_day,cursor_created,p_after)) and pro_daily_log_visible(p_actor,ctx,x) order by x.log_date desc,x.created_at desc,x.id desc limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('ownerId',own,'workId',p_work,'items',items,'nextCursor',cursor_id,'canCreate',is_owner or ctx->>'role'='contributor','canPublish',is_owner);
end $$;
-- Shared views read immutable versions and current recipients, never private rows.
create or replace function public.pro_daily_logs_shared_read(p_actor uuid,p_grant uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g pro_team_grants;items jsonb;cursor_id uuid;begin g:=pro_team_context(p_actor,p_grant,false);
 if p_actor=g.owner_id then raise exception 'Use owner view' using errcode='22023';end if;
 if p_after is not null and not exists(select 1 from pro_daily_log_audiences a where a.owner_id=g.owner_id and a.work_id=g.work_id and a.log_id=p_after and a.kind='team' and a.recipient_id=p_actor and a.grant_id=g.id and a.source_invite_id=g.source_invite_id) then raise exception 'Cursor changed' using errcode='40001';end if;
 with visible as(select distinct on(v.log_id)v.log_id,v.content from pro_daily_log_versions v join pro_daily_log_audiences a using(owner_id,work_id,log_id,version) where v.owner_id=g.owner_id and v.work_id=g.work_id and a.kind='team' and a.recipient_id=p_actor and a.grant_id=g.id and a.source_invite_id=g.source_invite_id and(p_after is null or v.log_id>p_after) order by v.log_id,v.version desc),page as(select * from visible order by log_id limit 21)select coalesce(jsonb_agg(content order by log_id),'[]'::jsonb) into items from page;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('ownerId',g.owner_id,'workId',g.work_id,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_daily_logs_client_read(p_actor uuid,p_request uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_appointment_requests;items jsonb;cursor_id uuid;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null and status in('confirmed','completed');if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null and not exists(select 1 from pro_daily_log_audiences a where a.owner_id=r.owner_id and a.work_id=r.work_id and a.log_id=p_after and a.kind='client' and a.recipient_id=p_actor and a.request_id=r.id) then raise exception 'Cursor changed' using errcode='40001';end if;
 with visible as(select distinct on(v.log_id)v.log_id,v.content from pro_daily_log_versions v join pro_daily_log_audiences a using(owner_id,work_id,log_id,version) where v.owner_id=r.owner_id and v.work_id=r.work_id and a.kind='client' and a.recipient_id=p_actor and a.request_id=r.id and(p_after is null or v.log_id>p_after) order by v.log_id,v.version desc),page as(select * from visible order by log_id limit 21)select coalesce(jsonb_agg(content order by log_id),'[]'::jsonb) into items from page;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('ownerId',r.owner_id,'workId',r.work_id,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_daily_log_audience_read(p_actor uuid,p_work text,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor_id uuid;begin
 perform pro_work_schedule_owner(p_actor,p_work);
 if p_after is not null and not exists(select 1 from pro_team_grants g join profiles p on p.id=g.member_user_id and not coalesce(p.is_disabled,false) where g.owner_id=p_actor and g.work_id=p_work and g.active and g.id=p_after) then raise exception 'Cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('grantId',g.id,'sourceInviteId',g.source_invite_id,'name',g.member_name) order by g.id),'[]'::jsonb) into items from(select g.* from pro_team_grants g join profiles p on p.id=g.member_user_id and not coalesce(p.is_disabled,false) where g.owner_id=p_actor and g.work_id=p_work and g.active and g.member_user_id<>p_actor and(p_after is null or g.id>p_after) order by g.id limit 21)g;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'grantId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_logs_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;lid uuid;target uuid;wid text;gid uuid;own uuid;rev integer;ctx jsonb;receipt pro_daily_log_actions;l pro_daily_logs;d pro_daily_log_defaults;g pro_team_grants;r pro_appointment_requests;keys text[];expected text[];is_owner boolean;before_json jsonb;after_json jsonb;answer jsonb;snapshot_json jsonb;weather_json jsonb;day date;task_ids uuid[];plan_ids uuid[];sections_json jsonb;ref jsonb;team_ids uuid[]:='{}';version_no integer;version_json jsonb;service_name text;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid identity' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if act in('create','update') then expected:=array['action','actionId','date','grantId','logId','revision','sections','source','summary','title','weather','workId'];
 elsif act='duplicate' then expected:=array['action','actionId','grantId','logId','revision','targetLogId','workId'];
 elsif act in('archive','restore') then expected:=array['action','actionId','grantId','logId','revision','workId'];
 elsif act='publish' then expected:=array['action','actionId','client','grantId','logId','revision','team','workId'];
 elsif act='defaults_save' then expected:=array['action','actionId','revision','sections','summary'];else raise exception 'Unknown daily log action' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected then raise exception 'Unexpected daily log fields' using errcode='22023';end if;
 if act='defaults_save' then if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;own:=p_actor;is_owner:=true;
 else
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'logId') is distinct from 'string' then raise exception 'Invalid scope' using errcode='22023';end if;
  wid:=p_input->>'workId';gid:=(p_input->>'grantId')::uuid;lid:=(p_input->>'logId')::uuid;ctx:=pro_daily_log_context(p_actor,wid,gid,true);own:=(ctx->>'ownerId')::uuid;is_owner:=(ctx->>'isOwner')::boolean;
  if act='publish' and not is_owner then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-action:'||p_actor::text||':'||aid::text,0));
 if act='defaults_save' then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-defaults:'||own::text,0));if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 else
  -- Same owner/work advisory as Team role/revoke and task/plan writers. Team
  -- takes grant rows after this advisory. Appointment writes request before work.
  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));
  if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
  ctx:=pro_daily_log_context(p_actor,wid,gid,true);if (ctx->>'ownerId')::uuid<>own then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 select * into receipt from pro_daily_log_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.work_id is distinct from wid or receipt.owner_id<>own or receipt.grant_id is distinct from(gid) or receipt.source_invite_id is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Forbidden' using errcode='42501';end if;
  if receipt.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return receipt.result;
 end if;
 if act='defaults_save' then
  if jsonb_typeof(p_input->'summary') is distinct from 'string' or length(p_input->>'summary')>2000 or jsonb_typeof(p_input->'sections') is distinct from 'object' or not pro_daily_log_sections_valid(p_input->'sections') then raise exception 'Invalid defaults' using errcode='22023';end if;
  select * into d from pro_daily_log_defaults where owner_id=own for update;if coalesce(d.revision,0)<>rev then raise exception 'Defaults changed' using errcode='40001';end if;
  before_json:=pro_daily_log_defaults_read(p_actor);insert into pro_daily_log_defaults(owner_id,revision,summary,sections) values(own,rev+1,btrim(p_input->>'summary'),p_input->'sections') on conflict(owner_id) do update set revision=excluded.revision,summary=excluded.summary,sections=excluded.sections;
  answer:=jsonb_build_object('action',act,'defaults',pro_daily_log_defaults_read(p_actor));after_json:=answer->'defaults';
 else
  if act='publish' then
   if jsonb_typeof(p_input->'client') not in('null','object') or jsonb_typeof(p_input->'team') is distinct from 'array' or jsonb_array_length(p_input->'team')>100 or p_input->'client'='null'::jsonb and jsonb_array_length(p_input->'team')=0 then raise exception 'Choose a bounded audience' using errcode='22023';end if;
   if p_input->'client'<>'null'::jsonb then
    if(select array_agg(key order by key) from jsonb_object_keys(p_input->'client')key) is distinct from array['recipientId','requestId'] then raise exception 'Invalid client audience' using errcode='22023';end if;
    select * into r from pro_appointment_requests where id=(p_input->'client'->>'requestId')::uuid and owner_id=own and work_id=wid for share;if not found then raise exception 'Client changed' using errcode='40001';end if;
   end if;
   for ref in select value from jsonb_array_elements(p_input->'team') order by value->>'grantId' loop
    if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['grantId','sourceInviteId'] or jsonb_typeof(ref->'grantId') is distinct from 'string' or jsonb_typeof(ref->'sourceInviteId') is distinct from 'string' then raise exception 'Invalid team audience' using errcode='22023';end if;
    if(ref->>'grantId')::uuid=any(team_ids) then raise exception 'Duplicate team audience' using errcode='22023';end if;team_ids:=array_append(team_ids,(ref->>'grantId')::uuid);
    select * into g from pro_team_grants where id=(ref->>'grantId')::uuid and owner_id=own and work_id=wid for share;
    if not found or not g.active or g.member_user_id=own or g.source_invite_id<>(ref->>'sourceInviteId')::uuid or not exists(select 1 from profiles where id=g.member_user_id and not coalesce(is_disabled,false)) then raise exception 'Team audience changed' using errcode='40001';end if;
   end loop;
  end if;
  -- Do not take a work row lock: existing appointment work guards acquire the
  -- request row while holding work UPDATE. Sources are one coherent MVCC read,
  -- captured with fingerprint CAS; cost commits afterward cannot rewrite it.
  perform 1 from pro_work where user_id=own and id=wid;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select * into l from pro_daily_logs where owner_id=own and work_id=wid and id=lid for update;
  if act='create' then if found or rev<>0 then raise exception 'Daily log identity changed' using errcode='40001';end if;
  else if not found or not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Forbidden' using errcode='42501';end if;if l.revision<>rev then raise exception 'Daily log changed' using errcode='40001';end if;before_json:=pro_daily_log_json(l);end if;
  if act in('create','duplicate') and(select count(*) from pro_daily_logs where owner_id=own and work_id=wid)>=500 then raise exception 'Daily log capacity exceeded' using errcode='40001';end if;
  if act in('create','update') then
   if act='update' and l.archived then raise exception 'Restore before editing' using errcode='40001';end if;
   if jsonb_typeof(p_input->'date') is distinct from 'string' or not coalesce((p_input->>'date')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) or jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or jsonb_typeof(p_input->'summary') is distinct from 'string' or length(p_input->>'summary')>2000 or jsonb_typeof(p_input->'sections') is distinct from 'object' or not pro_daily_log_sections_valid(p_input->'sections') or jsonb_typeof(p_input->'weather') not in('object','null') or jsonb_typeof(p_input->'source') is distinct from 'object' then raise exception 'Invalid daily log content' using errcode='22023';end if;
   day:=(p_input->>'date')::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid daily log date' using errcode='22023';end if;sections_json:=p_input->'sections';weather_json:=nullif(p_input->'weather','null'::jsonb);
   if not(sections_json->>'weather')::boolean and weather_json is not null then raise exception 'Weather section disabled' using errcode='22023';end if;
   if weather_json is not null then
    if(select array_agg(key order by key) from jsonb_object_keys(weather_json)key) is distinct from array['condition','note','temperatureC'] or weather_json->>'condition' not in('clear','cloudy','rain','other') or jsonb_typeof(weather_json->'condition') is distinct from 'string' or jsonb_typeof(weather_json->'note') is distinct from 'string' or length(weather_json->>'note')>300 or jsonb_typeof(weather_json->'temperatureC') not in('number','null') or(weather_json->>'temperatureC')::numeric not between -20 and 60 then raise exception 'Invalid manual weather' using errcode='22023';end if;
   end if;
   if p_input->'source'->>'mode'='keep' then
    if act='create' or p_input->'source'<>jsonb_build_object('mode','keep') or l.log_date<>day or l.sections<>sections_json then raise exception 'Refresh sources after changing date or sections' using errcode='22023';end if;snapshot_json:=l.snapshot;
   elsif p_input->'source'->>'mode'='capture' then
    if(select array_agg(key order by key) from jsonb_object_keys(p_input->'source')key) is distinct from array['fingerprint','mode','planTaskIds','taskIds'] or jsonb_typeof(p_input->'source'->'taskIds') is distinct from 'array' or jsonb_typeof(p_input->'source'->'planTaskIds') is distinct from 'array' or not coalesce((p_input->'source'->>'fingerprint')~'^[a-f0-9]{32}$',false) then raise exception 'Invalid source capture' using errcode='22023';end if;
    select coalesce(array_agg(value::uuid),'{}') into task_ids from jsonb_array_elements_text(p_input->'source'->'taskIds');select coalesce(array_agg(value::uuid),'{}') into plan_ids from jsonb_array_elements_text(p_input->'source'->'planTaskIds');
    if not(sections_json->>'tasks')::boolean and cardinality(task_ids)>0 or not(sections_json->>'plan')::boolean and cardinality(plan_ids)>0 then raise exception 'Disabled source section' using errcode='22023';end if;
    snapshot_json:=pro_daily_log_snapshot(p_actor,wid,gid,p_input->>'date',task_ids,plan_ids,(sections_json->>'time')::boolean);if snapshot_json->>'fingerprint'<>p_input->'source'->>'fingerprint' then raise exception 'Sources changed; refresh before saving' using errcode='40001';end if;
   else raise exception 'Invalid source mode' using errcode='22023';end if;
   if act='create' then
    insert into pro_daily_logs(owner_id,work_id,id,log_date,title,summary,sections,weather,snapshot,revision,created_by,created_by_name,created_grant_id,source_invite_id) values(own,wid,lid,day,btrim(p_input->>'title'),btrim(p_input->>'summary'),sections_json,weather_json,snapshot_json,1,p_actor,pro_team_name(p_actor),(ctx->>'grantId')::uuid,(ctx->>'sourceInviteId')::uuid) returning * into l;
   else update pro_daily_logs set log_date=day,title=btrim(p_input->>'title'),summary=btrim(p_input->>'summary'),sections=sections_json,weather=weather_json,snapshot=snapshot_json,revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;end if;
  elsif act='duplicate' then
   if jsonb_typeof(p_input->'targetLogId') is distinct from 'string' then raise exception 'Invalid duplicate identity' using errcode='22023';end if;target:=(p_input->>'targetLogId')::uuid;
   if exists(select 1 from pro_daily_logs where owner_id=own and work_id=wid and id=target) then raise exception 'Duplicate identity used' using errcode='40001';end if;
   insert into pro_daily_logs(owner_id,work_id,id,log_date,title,summary,sections,weather,snapshot,revision,created_by,created_by_name,created_grant_id,source_invite_id) values(own,wid,target,l.log_date,l.title,l.summary,l.sections,l.weather,l.snapshot,1,p_actor,pro_team_name(p_actor),(ctx->>'grantId')::uuid,(ctx->>'sourceInviteId')::uuid) returning * into l;
  elsif act in('archive','restore') then
   if l.archived=(act='archive') then raise exception 'Daily log status changed' using errcode='40001';end if;update pro_daily_logs set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;
  else
   if l.archived then raise exception 'Restore before publishing' using errcode='40001';end if;
   if p_input->'client'<>'null'::jsonb and(r.client_user_id is distinct from(p_input->'client'->>'recipientId')::uuid or r.status not in('confirmed','completed') or not exists(select 1 from profiles where id=r.client_user_id and not coalesce(is_disabled,false)) or exists(select 1 from pro_work where user_id=own and id=wid and coalesce(cancelled,false))) then raise exception 'Client audience changed' using errcode='40001';end if;
   if exists(select 1 from pro_team_grants target_grant where target_grant.id=any(team_ids) and(not target_grant.active or not exists(select 1 from profiles p where p.id=target_grant.member_user_id and not coalesce(p.is_disabled,false)))) then raise exception 'Team audience changed' using errcode='40001';end if;
   update pro_daily_logs set revision=revision+1,published_revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;
   select coalesce(max(version),0)+1 into version_no from pro_daily_log_versions where owner_id=own and work_id=wid and log_id=lid;select service into service_name from pro_work where user_id=own and id=wid;
   version_json:=jsonb_build_object('id',lid,'version',version_no,'date',to_char(l.log_date,'YYYY-MM-DD'),'title',l.title,'summary',l.summary,'sections',l.sections,'weather',l.weather,'snapshot',l.snapshot,'service',service_name,'authorName',l.created_by_name,'publishedAt',now());
   insert into pro_daily_log_versions values(own,wid,lid,version_no,l.revision,version_json);
   if p_input->'client'<>'null'::jsonb then insert into pro_daily_log_audiences(owner_id,work_id,log_id,version,kind,recipient_id,request_id) values(own,wid,lid,version_no,'client',r.client_user_id,r.id);end if;
   insert into pro_daily_log_audiences(owner_id,work_id,log_id,version,kind,recipient_id,grant_id,source_invite_id) select own,wid,lid,version_no,'team',target_grant.member_user_id,target_grant.id,target_grant.source_invite_id from pro_team_grants target_grant where target_grant.id=any(team_ids);
  end if;
  ctx:=pro_daily_log_context(p_actor,wid,gid,true);after_json:=pro_daily_log_json(l);answer:=jsonb_build_object('action',act,'log',after_json);if act='publish' then answer:=answer||jsonb_build_object('version',version_json);end if;
  insert into pro_daily_log_history(owner_id,work_id,log_id,action_id,actor_id,actor_name,action,before_log,after_log) values(own,wid,l.id,aid,p_actor,pro_team_name(p_actor),act,before_json,after_json);
 end if;
 if not coalesce(pro_appointment_enabled(own),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_daily_log_actions(actor_id,action_id,owner_id,work_id,grant_id,source_invite_id,input,result,before_state,after_state) values(p_actor,aid,own,wid,gid,case when ctx is null then null else(ctx->>'sourceInviteId')::uuid end,p_input,answer,before_json,after_json);return answer;
end $$;
create or replace function public.pro_daily_log_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_daily_log_actions;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 if r.work_id is null then if r.owner_id<>p_actor or not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 else ctx:=pro_daily_log_context(p_actor,r.work_id,r.grant_id,true);if(ctx->>'ownerId')::uuid<>r.owner_id or(ctx->>'sourceInviteId')::uuid is distinct from r.source_invite_id then raise exception 'Forbidden' using errcode='42501';end if;end if;
 return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));
end $$;
do $$declare tab text;fn record;begin
 foreach tab in array array['pro_daily_log_defaults','pro_daily_logs','pro_daily_log_actions','pro_daily_log_history','pro_daily_log_versions','pro_daily_log_audiences'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 foreach tab in array array['pro_daily_log_actions','pro_daily_log_history','pro_daily_log_versions','pro_daily_log_audiences'] loop execute format('drop trigger if exists pro_daily_immutable on public.%I',tab);execute format('create trigger pro_daily_immutable before update on public.%I for each row execute function public.pro_team_append_only()',tab);end loop;
 for fn in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_daily_log_context','pro_daily_log_json','pro_daily_log_visible','pro_daily_log_sections_valid','pro_daily_log_snapshot','pro_daily_log_options','pro_daily_log_defaults_read','pro_daily_logs_read','pro_daily_logs_shared_read','pro_daily_logs_client_read','pro_daily_log_audience_read','pro_daily_logs_mutate','pro_daily_log_action_read') loop execute format('revoke all on function %s from public,anon,authenticated',fn.signature);execute format('grant execute on function %s to service_role',fn.signature);end loop;
end $$;
commit;

-- ===== daily-log-discussion-local.sql =====
-- LOCAL PRO ONLY. Append-only comments on immutable published versions/channels.
-- No draft access, storage, notifications, messages, outbox, email or billing writes.
begin;
create table if not exists public.pro_daily_log_comments(
 id uuid primary key,owner_id uuid not null,work_id text not null,log_id uuid not null,version integer not null,channel text not null check(channel in('client','team')),
 actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),actor_side text not null check(actor_side in('owner','client','team')),grant_id uuid,source_invite_id uuid,
 text text not null check(length(btrim(text)) between 1 and 1000),at timestamptz not null default now(),
 foreign key(owner_id,work_id,log_id,version) references public.pro_daily_log_versions(owner_id,work_id,log_id,version) on delete cascade,
 check((actor_side='team')=(grant_id is not null and source_invite_id is not null)),check(actor_side='team' or grant_id is null and source_invite_id is null)
);
create index if not exists pro_daily_log_comments_thread on pro_daily_log_comments(owner_id,work_id,log_id,version,channel,at,id);
create table if not exists public.pro_daily_log_comment_actions(
 actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null references profiles(id) on delete cascade,
 work_id text not null,log_id uuid not null,version integer not null,channel text not null check(channel in('client','team')),generation uuid,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(owner_id,work_id,log_id,version) references pro_daily_log_versions(owner_id,work_id,log_id,version) on delete cascade
);
create or replace function public.pro_daily_log_comment_json(p_comment public.pro_daily_log_comments) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_comment.id,'actorId',p_comment.actor_id,'actorName',p_comment.actor_name,'text',p_comment.text,'at',p_comment.at)$$;
create or replace function public.pro_daily_log_discussion_context(p_actor uuid,p_scope jsonb,p_write boolean default false,p_generation uuid default null,p_check_generation boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare side text;wid text;lid uuid;ver integer;channel_name text;own uuid;g pro_team_grants;r pro_appointment_requests;keys text[];expected text[];can_write boolean;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_scope) is distinct from 'object' or jsonb_typeof(p_scope->'side') is distinct from 'string' or jsonb_typeof(p_scope->'logId') is distinct from 'string' or jsonb_typeof(p_scope->'version') is distinct from 'number' or not coalesce((p_scope->>'version')~'^[0-9]{1,10}$',false) or(p_scope->>'version')::numeric not between 1 and 2147483647 or jsonb_typeof(p_scope->'channel') is distinct from 'string' then raise exception 'Invalid discussion scope' using errcode='22023';end if;
 side:=p_scope->>'side';lid:=(p_scope->>'logId')::uuid;ver:=(p_scope->>'version')::integer;channel_name:=p_scope->>'channel';
 if side='owner' then expected:=array['channel','logId','side','version','workId'];elsif side='client' then expected:=array['channel','logId','requestId','side','version'];elsif side='team' then expected:=array['channel','grantId','logId','side','version'];else raise exception 'Invalid discussion side' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_scope)key;if keys is distinct from expected then raise exception 'Unexpected discussion scope fields' using errcode='22023';end if;
 if side='owner' then
  if channel_name not in('client','team') or jsonb_typeof(p_scope->'workId') is distinct from 'string' then raise exception 'Invalid owner scope' using errcode='22023';end if;wid:=p_scope->>'workId';own:=p_actor;perform pro_work_schedule_owner(p_actor,wid);can_write:=true;
 elsif side='client' then
  if channel_name<>'client' or jsonb_typeof(p_scope->'requestId') is distinct from 'string' then raise exception 'Invalid client scope' using errcode='22023';end if;
  select * into r from pro_appointment_requests where id=(p_scope->>'requestId')::uuid and client_user_id=p_actor and work_id is not null and status in('confirmed','completed');if not found then raise exception 'Forbidden' using errcode='42501';end if;own:=r.owner_id;wid:=r.work_id;can_write:=coalesce(pro_appointment_enabled(own),false);
  if not exists(select 1 from pro_daily_log_audiences a where a.owner_id=own and a.work_id=wid and a.log_id=lid and a.version=ver and a.kind='client' and a.recipient_id=p_actor and a.request_id=r.id) then raise exception 'Forbidden' using errcode='42501';end if;
 else
  if channel_name<>'team' or jsonb_typeof(p_scope->'grantId') is distinct from 'string' then raise exception 'Invalid team scope' using errcode='22023';end if;
  g:=pro_team_context(p_actor,(p_scope->>'grantId')::uuid,false);if p_actor=g.owner_id then raise exception 'Owners use their own scope' using errcode='22023';end if;own:=g.owner_id;wid:=g.work_id;
  -- A current member can discover that their own captured generation changed,
  -- but receives neither old publication nor receipt. Outsiders fail above.
  if p_write and g.role<>'contributor' then raise exception 'Read-only discussion' using errcode='42501';end if;
  if p_check_generation and p_generation is distinct from g.source_invite_id then raise exception 'Team generation changed' using errcode='40001';end if;
  if not exists(select 1 from pro_daily_log_audiences a where a.owner_id=own and a.work_id=wid and a.log_id=lid and a.version=ver and a.kind='team' and a.recipient_id=p_actor and a.grant_id=g.id and a.source_invite_id=g.source_invite_id) then raise exception 'Forbidden' using errcode='42501';end if;
  can_write:=g.role='contributor';
 end if;
 if side<>'team' and p_generation is not null then raise exception 'Unexpected team generation' using errcode='22023';end if;
 if not exists(select 1 from pro_daily_log_versions v where v.owner_id=own and v.work_id=wid and v.log_id=lid and v.version=ver) or not exists(select 1 from pro_daily_log_audiences a where a.owner_id=own and a.work_id=wid and a.log_id=lid and a.version=ver and a.kind=channel_name) then raise exception 'Published channel unavailable' using errcode='P0002';end if;
 if p_write and not can_write then raise exception 'Read-only discussion' using errcode='42501';end if;
 return jsonb_build_object('ownerId',own,'workId',wid,'logId',lid,'version',ver,'channel',channel_name,'generation',case when side='team' then g.source_invite_id else null end,'canComment',can_write);
end $$;
create or replace function public.pro_daily_log_discussion_read(p_actor uuid,p_scope jsonb,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;wid text;lid uuid;ver integer;channel_name text;items jsonb;cursor_time timestamptz;cursor_id uuid;publication jsonb;begin
 ctx:=pro_daily_log_discussion_context(p_actor,p_scope);own:=(ctx->>'ownerId')::uuid;wid:=ctx->>'workId';lid:=(ctx->>'logId')::uuid;ver:=(ctx->>'version')::integer;channel_name:=ctx->>'channel';
 if p_after is not null then select at into cursor_time from pro_daily_log_comments where owner_id=own and work_id=wid and log_id=lid and version=ver and channel=channel_name and id=p_after;if not found then raise exception 'Discussion cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(pro_daily_log_comment_json(c::public.pro_daily_log_comments) order by c.at desc,c.id desc),'[]'::jsonb) into items from(select * from pro_daily_log_comments where owner_id=own and work_id=wid and log_id=lid and version=ver and channel=channel_name and(p_after is null or(at,id)<(cursor_time,p_after)) order by at desc,id desc limit 21)c;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 select content into publication from pro_daily_log_versions where owner_id=own and work_id=wid and log_id=lid and version=ver;
 return jsonb_build_object('context',ctx,'publication',publication,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_daily_log_discussion_versions(p_actor uuid,p_work text,p_log uuid,p_after integer default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_version integer;begin
 perform pro_work_schedule_owner(p_actor,p_work);if not exists(select 1 from pro_daily_logs where owner_id=p_actor and work_id=p_work and id=p_log) then return null;end if;
 if p_after is not null and(p_after<1 or not exists(select 1 from pro_daily_log_versions where owner_id=p_actor and work_id=p_work and log_id=p_log and version=p_after)) then raise exception 'Version cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(jsonb_build_object('version',v.version,'title',v.content->'title','publishedAt',v.content->'publishedAt','channels',coalesce((select jsonb_agg(x.kind order by x.kind) from(select distinct a.kind from pro_daily_log_audiences a where a.owner_id=v.owner_id and a.work_id=v.work_id and a.log_id=v.log_id and a.version=v.version)x),'[]'::jsonb)) order by v.version desc),'[]'::jsonb) into items from(select * from pro_daily_log_versions where owner_id=p_actor and work_id=p_work and log_id=p_log and(p_after is null or version<p_after) order by version desc limit 21)v;
 if jsonb_array_length(items)>20 then cursor_version:=(items->19->>'version')::integer;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_version);
end $$;
create or replace function public.pro_daily_log_comment_write(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;wid text;lid uuid;ver integer;channel_name text;aid uuid;cid uuid;gen uuid;keys text[];receipt pro_daily_log_comment_actions;c pro_daily_log_comments;answer jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid comment operation' using errcode='22023';end if;select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','commentId','generation','scope','text'] or p_input->>'action' is distinct from 'comment' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'commentId') is distinct from 'string' or jsonb_typeof(p_input->'generation') not in('string','null') or jsonb_typeof(p_input->'text') is distinct from 'string' or length(btrim(p_input->>'text')) not between 1 and 1000 then raise exception 'Invalid comment fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;cid:=(p_input->>'commentId')::uuid;gen:=(p_input->>'generation')::uuid;
 ctx:=pro_daily_log_discussion_context(p_actor,p_input->'scope',true,gen,true);own:=(ctx->>'ownerId')::uuid;wid:=ctx->>'workId';lid:=(ctx->>'logId')::uuid;ver:=(ctx->>'version')::integer;channel_name:=ctx->>'channel';
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-comment-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));
 if p_input->'scope'->>'side'='client' then perform 1 from pro_appointment_requests where id=(p_input->'scope'->>'requestId')::uuid for share;
 elsif p_input->'scope'->>'side'='team' then perform 1 from pro_team_grants where id=(p_input->'scope'->>'grantId')::uuid for share;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-thread:'||own::text||':'||length(wid)::text||':'||wid||':'||lid::text||':'||ver::text||':'||channel_name,0));
 -- Recheck current audience/role/owner subscription and generation after waiting,
 -- before even looking up a committed actor receipt. Never lock the work row.
 ctx:=pro_daily_log_discussion_context(p_actor,p_input->'scope',true,gen,true);
 select * into receipt from pro_daily_log_comment_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Comment action identity reused' using errcode='22023';end if;return receipt.result;end if;
 if exists(select 1 from pro_daily_log_comments where id=cid) then raise exception 'Comment identity already used' using errcode='40001';end if;
 if(select count(*) from pro_daily_log_comments where owner_id=own and work_id=wid and log_id=lid and version=ver and channel=channel_name)>=1000 then raise exception 'Discussion limit reached' using errcode='40001';end if;
 insert into pro_daily_log_comments(id,owner_id,work_id,log_id,version,channel,actor_id,actor_name,actor_side,grant_id,source_invite_id,text) values(cid,own,wid,lid,ver,channel_name,p_actor,pro_team_name(p_actor),p_input->'scope'->>'side',case when p_input->'scope'->>'side'='team' then(p_input->'scope'->>'grantId')::uuid else null end,gen,btrim(p_input->>'text')) returning * into c;
 ctx:=pro_daily_log_discussion_context(p_actor,p_input->'scope',true,gen,true);answer:=jsonb_build_object('action','comment','comment',pro_daily_log_comment_json(c),'thread',ctx-'canComment');
 insert into pro_daily_log_comment_actions(actor_id,action_id,owner_id,work_id,log_id,version,channel,generation,input,result) values(p_actor,aid,own,wid,lid,ver,channel_name,gen,p_input,answer);return answer;
end $$;
create or replace function public.pro_daily_log_comment_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare receipt pro_daily_log_comment_actions;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into receipt from pro_daily_log_comment_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 ctx:=pro_daily_log_discussion_context(p_actor,receipt.input->'scope',true);
 if(ctx->>'generation')::uuid is distinct from receipt.generation then raise exception 'Receipt access changed' using errcode='42501';end if;
 return jsonb_build_object('receipt',jsonb_build_object('input',receipt.input,'result',receipt.result));
end $$;
alter table public.pro_daily_log_comments enable row level security;alter table public.pro_daily_log_comment_actions enable row level security;
revoke all on public.pro_daily_log_comments,public.pro_daily_log_comment_actions from public,anon,authenticated;
grant all on public.pro_daily_log_comments,public.pro_daily_log_comment_actions to service_role;
drop trigger if exists pro_daily_comment_immutable on public.pro_daily_log_comments;create trigger pro_daily_comment_immutable before update on public.pro_daily_log_comments for each row execute function public.pro_team_append_only();
drop trigger if exists pro_daily_comment_action_immutable on public.pro_daily_log_comment_actions;create trigger pro_daily_comment_action_immutable before update on public.pro_daily_log_comment_actions for each row execute function public.pro_team_append_only();
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_daily_log_comment_json','pro_daily_log_discussion_context','pro_daily_log_discussion_read','pro_daily_log_discussion_versions','pro_daily_log_comment_write','pro_daily_log_comment_action_read') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;

-- ===== daily-log-files-local.sql =====
-- LOCAL PRO ONLY. Immutable private blobs, explicit per-version/channel manifests.
-- No old table/function replacement, sends, notifications, messages or billing.
begin;
create table if not exists public.pro_daily_log_file_heads(owner_id uuid not null,work_id text not null,log_id uuid not null,revision integer not null check(revision>0),primary key(owner_id,work_id,log_id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_files(id uuid primary key,owner_id uuid not null,work_id text not null,log_id uuid not null,source_name text not null check(length(source_name) between 1 and 160),name text not null check(length(name) between 1 and 160),mime_type text not null check(mime_type in('image/jpeg','application/pdf')),size_bytes integer not null check(size_bytes between 1 and 20971520),raw_sha256 text not null check(raw_sha256~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),object_path text not null unique,ready boolean not null default false,ready_revision integer,created_by uuid not null,created_by_name text not null check(length(created_by_name)<=160),created_grant_id uuid,source_invite_id uuid,created_at timestamptz not null default now(),unique(owner_id,work_id,log_id,id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade,check((created_grant_id is null)=(source_invite_id is null)),check((ready and ready_revision is not null and ready_revision>0) or(not ready and ready_revision is null)),check(mime_type<>'image/jpeg' or size_bytes<=20971520),check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end));
create index if not exists pro_daily_log_files_page on pro_daily_log_files(owner_id,work_id,log_id,ready,id);
create table if not exists public.pro_daily_log_file_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null,work_id text not null,log_id uuid not null,grant_id uuid,generation uuid,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),result jsonb,before_state jsonb,after_state jsonb,at timestamptz not null default now(),primary key(actor_id,action_id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_published_files(owner_id uuid not null,work_id text not null,log_id uuid not null,version integer not null,channel text not null check(channel in('client','team')),file_id uuid not null,position integer not null check(position between 0 and 19),snapshot jsonb not null,primary key(owner_id,work_id,log_id,version,channel,file_id),unique(owner_id,work_id,log_id,version,channel,position),foreign key(owner_id,work_id,log_id,version) references pro_daily_log_versions(owner_id,work_id,log_id,version) on delete cascade,foreign key(owner_id,work_id,log_id,file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete no action deferrable initially deferred);
create or replace function public.pro_daily_log_file_json(p_file public.pro_daily_log_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_file.id,'ownerId',p_file.owner_id,'workId',p_file.work_id,'logId',p_file.log_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,'sha256',p_file.sha256,'ready',p_file.ready,'createdBy',p_file.created_by,'createdByName',p_file.created_by_name,'createdGrantId',p_file.created_grant_id,'sourceInviteId',p_file.source_invite_id,'createdAt',p_file.created_at)$$;
create or replace function public.pro_daily_log_file_snapshot(p_file public.pro_daily_log_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select pro_daily_log_file_json(p_file)-array['ownerId','workId','logId','ready','createdBy','createdByName','createdGrantId','sourceInviteId']$$;
create or replace function public.pro_daily_log_file_context(p_actor uuid,p_work text,p_log uuid,p_grant uuid default null,p_write boolean default false,p_generation uuid default null,p_check_generation boolean default false,p_allow_missing boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;l pro_daily_logs;head integer;has_log boolean;can_upload boolean;begin
 ctx:=pro_daily_log_context(p_actor,p_work,p_grant,false);own:=(ctx->>'ownerId')::uuid;
 if p_write and not((ctx->>'isOwner')::boolean or ctx->>'role'='contributor') then raise exception 'Read-only file access' using errcode='42501';end if;
 if p_check_generation and p_generation is distinct from(ctx->>'sourceInviteId')::uuid then if p_write then raise exception 'Upload generation changed' using errcode='40001';else raise exception 'Upload generation changed' using errcode='42501';end if;end if;
 select * into l from pro_daily_logs where owner_id=own and work_id=p_work and id=p_log;has_log:=found;
 if has_log then if not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Private log unavailable' using errcode='42501';end if;
 elsif not p_allow_missing then raise exception 'Save the draft before uploading' using errcode='42501';end if;
 can_upload:=((ctx->>'isOwner')::boolean or ctx->>'role'='contributor') and(not has_log or not l.archived);
 if p_write and(not has_log or not can_upload) then raise exception 'Upload access unavailable' using errcode='42501';end if;
 select revision into head from pro_daily_log_file_heads where owner_id=own and work_id=p_work and log_id=p_log;
 return jsonb_build_object('ownerId',own,'workId',p_work,'logId',p_log,'grantId',p_grant,'generation',(ctx->>'sourceInviteId')::uuid,'exists',has_log,'canUpload',can_upload,'revision',coalesce(head,0));
end $$;
create or replace function public.pro_daily_log_file_head_advance(p_owner uuid,p_work text,p_log uuid) returns integer language plpgsql security invoker set search_path=public,pg_temp as $$declare head integer;begin select revision into head from pro_daily_log_file_heads where owner_id=p_owner and work_id=p_work and log_id=p_log for update;head:=coalesce(head,0);if head>=2147483647 then raise exception 'File revision exhausted' using errcode='40001';end if;insert into pro_daily_log_file_heads values(p_owner,p_work,p_log,head+1) on conflict(owner_id,work_id,log_id) do update set revision=excluded.revision;return head+1;end $$;
create or replace function public.pro_daily_log_files_read(p_actor uuid,p_work text,p_log uuid,p_grant uuid default null,p_status text default 'ready',p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare ctx jsonb;own uuid;items jsonb;cursor_id uuid;begin
 ctx:=pro_daily_log_file_context(p_actor,p_work,p_log,p_grant);own:=(ctx->>'ownerId')::uuid;if p_status is null or p_status not in('ready','pending','all') then raise exception 'Invalid file status' using errcode='22023';end if;
 if p_after is not null and not exists(select 1 from pro_daily_log_files where owner_id=own and work_id=p_work and log_id=p_log and id=p_after and(p_status='all' or ready=(p_status='ready'))) then raise exception 'File cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(pro_daily_log_file_json(f::public.pro_daily_log_files) order by f.id),'[]'::jsonb) into items from(select * from pro_daily_log_files where owner_id=own and work_id=p_work and log_id=p_log and(p_status='all' or ready=(p_status='ready')) and(p_after is null or id>p_after) order by id limit 21)f;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('context',ctx,'items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_log_published_files_read(p_actor uuid,p_scope jsonb,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare ctx jsonb;items jsonb;cursor_pos integer;cursor_id uuid;begin
 ctx:=pro_daily_log_discussion_context(p_actor,p_scope);if p_after is not null then select position into cursor_pos from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and file_id=p_after;if not found then raise exception 'Published file cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(f.snapshot order by f.position,f.file_id),'[]'::jsonb) into items from(select * from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and(p_after is null or(position,file_id)>(cursor_pos,p_after)) order by position,file_id limit 21)f;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('context',ctx,'items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_log_file_download(p_actor uuid,p_file uuid,p_work text default null,p_log uuid default null,p_grant uuid default null,p_generation uuid default null,p_check_generation boolean default false,p_scope jsonb default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;f pro_daily_log_files;manifest jsonb;begin
 if p_scope is null then ctx:=pro_daily_log_file_context(p_actor,p_work,p_log,p_grant,false,p_generation,p_check_generation);select * into f from pro_daily_log_files where id=p_file and owner_id=(ctx->>'ownerId')::uuid and work_id=p_work and log_id=p_log and ready;
 else ctx:=pro_daily_log_discussion_context(p_actor,p_scope);select snapshot into manifest from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and file_id=p_file;if not found then return null;end if;select * into f from pro_daily_log_files where id=p_file and owner_id=(ctx->>'ownerId')::uuid and ready;end if;
 if f.id is null then return null;end if;return jsonb_build_object('objectPath',f.object_path,'name',coalesce(manifest->>'name',f.name),'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);end $$;
create or replace function public.pro_daily_log_file_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;ctx jsonb;f pro_daily_log_files;source pro_daily_log_files;begin
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);if r.result is not null then return jsonb_build_object('result',r.result);end if;
 select * into f from pro_daily_log_files where owner_id=r.owner_id and work_id=r.work_id and log_id=r.log_id and id=(r.input->>'fileId')::uuid;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 if r.input->>'action'='copy' then perform pro_daily_log_file_context(p_actor,r.work_id,(r.input->>'sourceLogId')::uuid,r.grant_id);end if;
 return jsonb_build_object('result',null,'file',pro_daily_log_file_json(f),'objectPath',f.object_path,'source',r.before_state);
end $$;
create or replace function public.pro_daily_log_file_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;fid uuid;wid text;lid uuid;gid uuid;gen uuid;ctx jsonb;own uuid;keys text[];expected text[];r pro_daily_log_file_actions;f pro_daily_log_files;source pro_daily_log_files;before_json jsonb;mime text;bytes integer;filename text;head integer;begin
 if jsonb_typeof(p_input) is distinct from 'object' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) then raise exception 'Invalid file operation' using errcode='22023';end if;act:=p_input->>'action';
 if act='upload' then expected:=array['action','actionId','fileId','generation','grantId','logId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName','workId'];elsif act='copy' then expected:=array['action','actionId','fileId','generation','grantId','logId','sourceFileId','sourceLogId','sourceSha256','workId'];else raise exception 'Invalid file action' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') then raise exception 'Invalid file fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;gid:=(p_input->>'grantId')::uuid;gen:=(p_input->>'generation')::uuid;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);own:=(ctx->>'ownerId')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'File action identity reused' using errcode='22023';end if;return pro_daily_log_file_pending(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_files where id=fid) then raise exception 'File identity already used' using errcode='40001';end if;
 if(select count(*) from pro_daily_log_files where owner_id=own and work_id=wid)>=100 then raise exception 'File capacity exceeded' using errcode='40001';end if;
 if act='copy' then
  if jsonb_typeof(p_input->'sourceLogId') is distinct from 'string' or jsonb_typeof(p_input->'sourceFileId') is distinct from 'string' or not coalesce((p_input->>'sourceSha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid copy source' using errcode='22023';end if;
  perform pro_daily_log_file_context(p_actor,wid,(p_input->>'sourceLogId')::uuid,gid);
  select * into source from pro_daily_log_files where owner_id=own and work_id=wid and log_id=(p_input->>'sourceLogId')::uuid and id=(p_input->>'sourceFileId')::uuid and ready for share;if not found then raise exception 'Copy source unavailable' using errcode='42501';end if;if source.sha256<>p_input->>'sourceSha256' then raise exception 'Copy source changed' using errcode='40001';end if;
  mime:=source.mime_type;bytes:=source.size_bytes;filename:=source.name;before_json:=jsonb_build_object('file',pro_daily_log_file_json(source),'objectPath',source.object_path);
 else
  if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string' or length(p_input->>'sourceName') not between 1 and 160 or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or p_input->>'mimeType' not in('image/jpeg','application/pdf') or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid canonical upload' using errcode='22023';end if;
  mime:=p_input->>'mimeType';bytes:=(p_input->>'sizeBytes')::integer;filename:=p_input->>'name';
 end if;
 if bytes not between 1 and 20971520 or mime='image/jpeg' and bytes>20971520 or length(filename) not between 1 and 160 or filename~'[[:cntrl:]/\\]' or mime='application/pdf' and right(filename,4)<>'.pdf' or mime='image/jpeg' and right(filename,4)<>'.jpg' then raise exception 'Invalid canonical file metadata' using errcode='22023';end if;
 head:=pro_daily_log_file_head_advance(own,wid,lid);
 insert into pro_daily_log_files(id,owner_id,work_id,log_id,source_name,name,mime_type,size_bytes,raw_sha256,sha256,object_path,created_by,created_by_name,created_grant_id,source_invite_id) values(fid,own,wid,lid,case when act='copy' then source.name else p_input->>'sourceName' end,filename,mime,bytes,case when act='copy' then source.sha256 else p_input->>'rawSha256' end,case when act='copy' then source.sha256 else p_input->>'sha256' end,own::text||'/'||fid::text||case when mime='application/pdf' then '.pdf' else '.jpg' end,p_actor,pro_team_name(p_actor),gid,gen) returning * into f;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);
 insert into pro_daily_log_file_actions(actor_id,action_id,owner_id,work_id,log_id,grant_id,generation,input,input_hash,before_state) values(p_actor,aid,own,wid,lid,gid,gen,p_input,p_input_hash,before_json);return pro_daily_log_file_pending(p_actor,aid);
end $$;
create or replace function public.pro_daily_log_file_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_daily_log_file_actions;ctx jsonb;f pro_daily_log_files;head integer;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found or r.input->>'action' not in('upload','copy') then raise exception 'Upload reservation unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||r.owner_id::text||':'||r.work_id,0));if r.grant_id is not null then perform 1 from pro_team_grants where id=r.grant_id for share;end if;
 ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);if r.result is not null then return r.result;end if;
 if r.input->>'action'='copy' then perform pro_daily_log_file_context(p_actor,r.work_id,(r.input->>'sourceLogId')::uuid,r.grant_id);end if;
 select * into f from pro_daily_log_files where id=(r.input->>'fileId')::uuid and owner_id=r.owner_id and work_id=r.work_id and log_id=r.log_id for update;if not found or f.ready then raise exception 'Upload state changed' using errcode='40001';end if;
 head:=pro_daily_log_file_head_advance(r.owner_id,r.work_id,r.log_id);update pro_daily_log_files set ready=true,ready_revision=head where id=f.id returning * into f;
 answer:=jsonb_build_object('action',r.input->>'action','file',pro_daily_log_file_json(f),'revision',head);ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);
 update pro_daily_log_file_actions set result=answer,after_state=answer where actor_id=p_actor and action_id=p_action;return answer;
end $$;
-- Both the legacy HTTP facade and the new publication endpoint call this wrapper.
-- Missing `files` stays missing in receipts. Old stored writer receipts stay untouched.
create or replace function public.pro_daily_log_publish_files(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;lid uuid;keys text[];old_input jsonb;r pro_daily_log_file_actions;old_receipt pro_daily_log_actions;l pro_daily_logs;f pro_daily_log_files;ref jsonb;gref jsonb;channel_name text;head integer;ver integer;pos integer;client_files jsonb:='[]';team_files jsonb:='[]';snap jsonb;publication jsonb;answer jsonb;selected uuid[];begin
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'publish' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' then raise exception 'Invalid publication' using errcode='22023';end if;
 old_input:=p_input-'files';select array_agg(key order by key) into keys from jsonb_object_keys(old_input)key;if keys is distinct from array['action','actionId','client','grantId','logId','revision','team','workId'] or old_input->'grantId' is distinct from 'null'::jsonb then raise exception 'Invalid owner publication fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;perform pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-action:'||p_actor::text||':'||aid::text,0));perform pro_work_schedule_owner(p_actor,wid);
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Publication identity reused with different files' using errcode='22023';end if;return r.result;end if;
 select * into old_receipt from pro_daily_log_actions where actor_id=p_actor and action_id=aid;
 if found then
  if p_input?'files' or old_receipt.input is distinct from old_input then raise exception 'Legacy publication identity cannot acquire attachments' using errcode='22023';end if;
  publication:=pro_daily_logs_mutate(p_actor,old_input);return jsonb_build_object('action','publish','publication',publication,'files',jsonb_build_object('client','[]'::jsonb,'team','[]'::jsonb));
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 -- Same request/grant/log ordering as the old writer; no work row lock.
 if old_input->'client'<>'null'::jsonb then perform 1 from pro_appointment_requests where id=(old_input->'client'->>'requestId')::uuid and owner_id=p_actor and work_id=wid for share;end if;
 if jsonb_typeof(old_input->'team') is distinct from 'array' then raise exception 'Invalid team audience' using errcode='22023';end if;
 for gref in select value from jsonb_array_elements(old_input->'team') order by value->>'grantId' loop perform 1 from pro_team_grants where id=(gref->>'grantId')::uuid and owner_id=p_actor and work_id=wid for share;end loop;
 select * into l from pro_daily_logs where owner_id=p_actor and work_id=wid and id=lid for update;if not found then raise exception 'Log unavailable' using errcode='42501';end if;
 if p_input?'files' then
  if jsonb_typeof(p_input->'files') is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input->'files')key) is distinct from array['client','revision','team'] or jsonb_typeof(p_input->'files'->'revision') is distinct from 'number' or not coalesce((p_input->'files'->>'revision')~'^[0-9]{1,10}$',false) or(p_input->'files'->>'revision')::numeric not between 0 and 2147483647 then raise exception 'Invalid file selection' using errcode='22023';end if;
  select revision into head from pro_daily_log_file_heads where owner_id=p_actor and work_id=wid and log_id=lid;head:=coalesce(head,0);if head<>(p_input->'files'->>'revision')::integer then raise exception 'Private files changed' using errcode='40001';end if;
  foreach channel_name in array array['client','team'] loop
   if jsonb_typeof(p_input->'files'->channel_name) is distinct from 'array' or jsonb_array_length(p_input->'files'->channel_name)>20 or(channel_name='client' and old_input->'client'='null'::jsonb or channel_name='team' and jsonb_array_length(old_input->'team')=0) and jsonb_array_length(p_input->'files'->channel_name)>0 then raise exception 'Files require their publication audience' using errcode='22023';end if;
   selected:='{}';for ref in select value from jsonb_array_elements(p_input->'files'->channel_name) loop
    if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['id','sha256'] or jsonb_typeof(ref->'id') is distinct from 'string' or not coalesce((ref->>'sha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid selected file' using errcode='22023';end if;
    if(ref->>'id')::uuid=any(selected) then raise exception 'Duplicate selected file' using errcode='22023';end if;selected:=array_append(selected,(ref->>'id')::uuid);
    select * into f from pro_daily_log_files where id=(ref->>'id')::uuid and owner_id=p_actor and work_id=wid and log_id=lid and ready for share;if not found or f.sha256<>ref->>'sha256' then raise exception 'Selected file changed or unavailable' using errcode='40001';end if;
    snap:=pro_daily_log_file_snapshot(f);if channel_name='client' then client_files:=client_files||jsonb_build_array(snap);else team_files:=team_files||jsonb_build_array(snap);end if;
   end loop;
  end loop;
 end if;
 publication:=pro_daily_logs_mutate(p_actor,old_input);ver:=(publication->'version'->>'version')::integer;
 foreach channel_name in array array['client','team'] loop pos:=0;for snap in select value from jsonb_array_elements(case when channel_name='client' then client_files else team_files end) loop insert into pro_daily_log_published_files values(p_actor,wid,lid,ver,channel_name,(snap->>'id')::uuid,pos,snap);pos:=pos+1;end loop;end loop;
 answer:=jsonb_build_object('action','publish','publication',publication,'files',jsonb_build_object('client',client_files,'team',team_files));perform pro_work_schedule_owner(p_actor,wid);
 insert into pro_daily_log_file_actions(actor_id,action_id,owner_id,work_id,log_id,input,input_hash,result,before_state,after_state) values(p_actor,aid,p_actor,wid,lid,p_input,p_input_hash,answer,pro_daily_log_json(l),answer);return answer;
end $$;
create or replace function public.pro_daily_log_file_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 if r.input->>'action'='publish' then perform pro_work_schedule_owner(p_actor,r.work_id);else ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true);if(ctx->>'generation')::uuid is distinct from r.generation then raise exception 'Receipt generation changed' using errcode='42501';end if;end if;
 if r.result is null then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'result',r.result));end $$;
create or replace function public.pro_daily_log_file_legacy_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;begin
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if found then perform pro_work_schedule_owner(p_actor,r.work_id);if r.input->>'action'<>'publish' or r.input?'files' then raise exception 'Action belongs to the attachment flow' using errcode='22023';end if;end if;return pro_daily_log_action_read(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.ready or not new.ready or new.ready_revision is null or(to_jsonb(new)-array['ready','ready_revision']) is distinct from(to_jsonb(old)-array['ready','ready_revision']) then raise exception 'Daily log file is immutable' using errcode='23514';end if;return new;end $$;
create or replace function public.pro_daily_log_file_action_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.result is not null or new.result is null or(to_jsonb(new)-array['result','after_state']) is distinct from(to_jsonb(old)-array['result','after_state']) then raise exception 'Daily log file receipt is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_daily_log_file_immutable on pro_daily_log_files;create trigger pro_daily_log_file_immutable before update on pro_daily_log_files for each row execute function pro_daily_log_file_immutable();
drop trigger if exists pro_daily_log_file_action_immutable on pro_daily_log_file_actions;create trigger pro_daily_log_file_action_immutable before update on pro_daily_log_file_actions for each row execute function pro_daily_log_file_action_immutable();
drop trigger if exists pro_daily_log_published_file_immutable on pro_daily_log_published_files;create trigger pro_daily_log_published_file_immutable before update on pro_daily_log_published_files for each row execute function pro_team_append_only();
do $$declare tab text;f record;begin foreach tab in array array['pro_daily_log_file_heads','pro_daily_log_files','pro_daily_log_file_actions','pro_daily_log_published_files'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_daily_log_file_json','pro_daily_log_file_snapshot','pro_daily_log_file_context','pro_daily_log_file_head_advance','pro_daily_log_files_read','pro_daily_log_published_files_read','pro_daily_log_file_download','pro_daily_log_file_pending','pro_daily_log_file_reserve','pro_daily_log_file_ready','pro_daily_log_publish_files','pro_daily_log_file_action_read','pro_daily_log_file_legacy_action_read','pro_daily_log_file_immutable','pro_daily_log_file_action_immutable') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
do $$begin if to_regclass('storage.buckets') is not null then insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-daily-log-files','pro-daily-log-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;if not exists(select 1 from storage.buckets where id='pro-daily-log-files' and not public and file_size_limit=20971520 and cardinality(allowed_mime_types)=2 and allowed_mime_types @> array['image/jpeg','application/pdf']) then raise exception 'Private daily log bucket contract mismatch';end if;end if;
 if to_regclass('storage.objects') is not null then execute 'drop policy if exists pro_daily_log_files_no_direct on storage.objects';execute 'create policy pro_daily_log_files_no_direct on storage.objects as restrictive for all to anon,authenticated using(bucket_id <> ''pro-daily-log-files'') with check(bucket_id <> ''pro-daily-log-files'')';end if;end $$;
commit;

-- ===== daily-log-file-reconciliation-local.sql =====
-- LOCAL PRO ONLY. Owner verifies existing canonical objects; no storage writes,
-- deletes, actor impersonation, original receipt changes or notifications.
begin;
create table if not exists public.pro_daily_log_file_reconcile_actions(
 owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,work_id text not null,log_id uuid not null,file_id uuid not null,
 input jsonb not null,baseline jsonb not null,original_actor_id uuid not null,original_actor_name text not null,original_action_id uuid,original_grant_id uuid,original_generation uuid,
 requested_name text not null,reserved_at timestamptz not null default now(),reason text check(reason in('missing_object','mismatch','unavailable')),outcome text check(outcome in('completed','already_ready')),result jsonb,
 primary key(owner_id,action_id),foreign key(owner_id,work_id,log_id,file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete cascade,
 check((outcome is null)=(result is null)),check(result is null or reason is null)
);
create unique index if not exists pro_daily_file_one_retirement on pro_daily_log_file_reconcile_actions(file_id) where outcome='completed';
create index if not exists pro_daily_file_retired_actor_action on pro_daily_log_file_reconcile_actions(original_actor_id,original_action_id) where outcome='completed';
create index if not exists pro_daily_file_reconcile_history on pro_daily_log_file_reconcile_actions(owner_id,work_id,log_id,reserved_at desc,action_id desc);
create table if not exists public.pro_daily_log_file_reconcile_events(owner_id uuid not null,action_id uuid not null,kind text not null check(kind in('reserved','confirmed','missing_object','mismatch','unavailable')),actor_id uuid not null,actor_name text not null,at timestamptz not null default now(),primary key(owner_id,action_id,kind),foreign key(owner_id,action_id) references pro_daily_log_file_reconcile_actions(owner_id,action_id) on delete cascade);
create or replace function public.pro_daily_file_reconcile_json(p_action public.pro_daily_log_file_reconcile_actions) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('input',p_action.input,'baseline',p_action.baseline,'phase',case when p_action.result is null then 'pending' else 'confirmed' end,'result',p_action.result,'reservedAt',p_action.reserved_at,'reason',p_action.reason)$$;
create or replace function public.pro_daily_file_reconcile_owner(p_actor uuid,p_work text,p_log uuid,p_write boolean default false) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin perform pro_work_schedule_owner(p_actor,p_work);if not exists(select 1 from pro_daily_logs where owner_id=p_actor and work_id=p_work and id=p_log) then raise exception 'Daily log unavailable' using errcode='42501';end if;if p_write and exists(select 1 from pro_daily_logs where owner_id=p_actor and work_id=p_work and id=p_log and archived) then raise exception 'Restore the daily log first' using errcode='40001';end if;end $$;
-- Permanent retirement is scoped to the original uploader/operation, not the file
-- author metadata. Historical public downloads keep their independent audience ACL.
create or replace function public.pro_daily_file_retirement_guard(p_actor uuid,p_action uuid,p_file uuid default null) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_file_reconcile_actions where outcome='completed' and original_actor_id=p_actor and(original_action_id=p_action or p_file is not null and file_id=p_file)) then raise exception 'The owner completed this pending upload' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action) then raise exception 'Action belongs to file reconciliation' using errcode='22023';end if;
end $$;
create or replace function public.pro_daily_file_reconcile_reserve(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;lid uuid;fid uuid;keys text[];a pro_daily_log_file_reconcile_actions;f pro_daily_log_files;original_aid uuid;original_actor uuid;begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid reconciliation' using errcode='22023';end if;select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','fileId','logId','sha256','workId'] or p_input->>'action' is distinct from 'reconcile' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid reconciliation fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;fid:=(p_input->>'fileId')::uuid;perform pro_daily_file_reconcile_owner(p_actor,wid,lid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||aid::text,0));
 select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=aid;if found then if a.input is distinct from p_input then raise exception 'Reconciliation identity reused' using errcode='22023';end if;return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a),'objectPath',a.owner_id::text||'/'||a.file_id::text||case when a.baseline->>'mimeType'='application/pdf' then '.pdf' else '.jpg' end);end if;
 if exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) then raise exception 'Action identity already used' using errcode='22023';end if;
 select * into f from pro_daily_log_files where owner_id=p_actor and work_id=wid and log_id=lid and id=fid;if not found then raise exception 'File unavailable' using errcode='42501';end if;if f.sha256<>p_input->>'sha256' then raise exception 'File hash changed' using errcode='40001';end if;
 original_actor:=f.created_by;select action_id into original_aid from pro_daily_log_file_actions where actor_id=original_actor and owner_id=p_actor and work_id=wid and log_id=lid and input->>'fileId'=fid::text and input->>'action' in('upload','copy') order by at,action_id limit 1;
 if original_aid is not null then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||original_actor::text||':'||original_aid::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));if f.created_grant_id is not null then perform 1 from pro_team_grants where id=f.created_grant_id for share;end if;
 perform pro_daily_file_reconcile_owner(p_actor,wid,lid,true);select * into f from pro_daily_log_files where owner_id=p_actor and work_id=wid and log_id=lid and id=fid for update;if not found or f.sha256<>p_input->>'sha256' then raise exception 'File changed' using errcode='40001';end if;
 insert into pro_daily_log_file_reconcile_actions(owner_id,action_id,work_id,log_id,file_id,input,baseline,original_actor_id,original_actor_name,original_action_id,original_grant_id,original_generation,requested_name) values(p_actor,aid,wid,lid,fid,p_input,pro_daily_log_file_json(f),f.created_by,f.created_by_name,original_aid,f.created_grant_id,f.source_invite_id,pro_team_name(p_actor)) returning * into a;
 insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,aid,'reserved',p_actor,pro_team_name(p_actor));perform pro_daily_file_reconcile_owner(p_actor,wid,lid,true);
 return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a),'objectPath',f.object_path);
end $$;
create or replace function public.pro_daily_file_reconcile_note(p_actor uuid,p_action uuid,p_reason text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare a pro_daily_log_file_reconcile_actions;begin
 if p_reason is null or p_reason not in('missing_object','mismatch','unavailable') then raise exception 'Invalid pending reason' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||p_action::text,0));select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action for update;if not found then raise exception 'Reconciliation unavailable' using errcode='42501';end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);
 if a.result is null then update pro_daily_log_file_reconcile_actions set reason=p_reason where owner_id=p_actor and action_id=p_action returning * into a;insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,p_action,p_reason,p_actor,pro_team_name(p_actor)) on conflict(owner_id,action_id,kind) do nothing;end if;return pro_daily_file_reconcile_json(a);
end $$;
create or replace function public.pro_daily_file_reconcile_finish(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare a pro_daily_log_file_reconcile_actions;f pro_daily_log_files;head integer;outcome_text text;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-reconcile:'||p_actor::text||':'||p_action::text,0));select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Reconciliation unavailable' using errcode='42501';end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);if a.result is not null then return pro_daily_file_reconcile_json(a);end if;
 if a.original_action_id is not null then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||a.original_actor_id::text||':'||a.original_action_id::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||a.work_id,0));if a.original_grant_id is not null then perform 1 from pro_team_grants where id=a.original_grant_id for share;end if;
 perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);select * into f from pro_daily_log_files where owner_id=p_actor and work_id=a.work_id and log_id=a.log_id and id=a.file_id for update;if not found or f.sha256<>a.input->>'sha256' then raise exception 'File changed' using errcode='40001';end if;
 if f.ready then outcome_text:='already_ready';select revision into head from pro_daily_log_file_heads where owner_id=p_actor and work_id=a.work_id and log_id=a.log_id;head:=coalesce(head,f.ready_revision);
 else outcome_text:='completed';head:=pro_daily_log_file_head_advance(p_actor,a.work_id,a.log_id);update pro_daily_log_files set ready=true,ready_revision=head where id=a.file_id returning * into f;end if;
 -- Required final reauthorization AFTER any head-row wait and file transition.
 -- A concurrent membership revocation rolls back ready/head/retirement/audit.
 perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);
 answer:=jsonb_build_object('action','reconcile','outcome',outcome_text,'file',pro_daily_log_file_json(f),'revision',head,'verifiedBy',jsonb_build_object('id',p_actor,'name',pro_team_name(p_actor),'at',now()));
 update pro_daily_log_file_reconcile_actions set reason=null,outcome=outcome_text,result=answer where owner_id=p_actor and action_id=p_action returning * into a;
 insert into pro_daily_log_file_reconcile_events(owner_id,action_id,kind,actor_id,actor_name) values(p_actor,p_action,'confirmed',p_actor,pro_team_name(p_actor));perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id,true);return pro_daily_file_reconcile_json(a);
end $$;
create or replace function public.pro_daily_file_reconcile_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare a pro_daily_log_file_reconcile_actions;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('attempt',null);end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a));end $$;
create or replace function public.pro_daily_file_reconcile_history(p_actor uuid,p_work text,p_log uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor_at timestamptz;cursor_id uuid;begin
 perform pro_daily_file_reconcile_owner(p_actor,p_work,p_log);
 if p_after is not null then select reserved_at into cursor_at from pro_daily_log_file_reconcile_actions where owner_id=p_actor and work_id=p_work and log_id=p_log and action_id=p_after;if not found then raise exception 'History cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',a.action_id,'fileId',a.file_id,'fileName',a.baseline->>'name','originalActorId',a.original_actor_id,'originalActorName',a.original_actor_name,'phase',case when a.result is null then 'pending' else 'confirmed' end,'reason',a.reason,'requestedBy',jsonb_build_object('id',a.owner_id,'name',a.requested_name),'reservedAt',a.reserved_at,'outcome',a.outcome,'verifiedAt',a.result->'verifiedBy'->'at','verifiedByName',a.result->'verifiedBy'->>'name') order by a.reserved_at desc,a.action_id desc),'[]'::jsonb) into items from(select * from pro_daily_log_file_reconcile_actions where owner_id=p_actor and work_id=p_work and log_id=p_log and(p_after is null or(reserved_at,action_id)<(cursor_at,p_after)) order by reserved_at desc,action_id desc limit 21)a;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
-- Guarded facades share the ORIGINAL operation advisory. Retirement cannot race
-- between the guard and old reserve/ready execution; old SQL remains unchanged.
create or replace function public.pro_daily_log_file_reserve_guarded(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;begin aid:=(p_input->>'actionId')::uuid;perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));perform pro_daily_file_retirement_guard(p_actor,aid,(p_input->>'fileId')::uuid);return pro_daily_log_file_reserve(p_actor,p_input,p_input_hash);end $$;
create or replace function public.pro_daily_log_file_pending_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_pending(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_ready_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_ready(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_action_read_guarded(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$begin perform pro_daily_file_retirement_guard(p_actor,p_action);return pro_daily_log_file_action_read(p_actor,p_action);end $$;
create or replace function public.pro_daily_file_reconcile_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if old.result is not null or(to_jsonb(new)-array['reason','outcome','result']) is distinct from(to_jsonb(old)-array['reason','outcome','result']) or new.result is null and new.outcome is not null or new.result is not null and(new.outcome is null or new.reason is not null) then raise exception 'Reconciliation history is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_daily_file_reconcile_immutable on pro_daily_log_file_reconcile_actions;create trigger pro_daily_file_reconcile_immutable before update on pro_daily_log_file_reconcile_actions for each row execute function pro_daily_file_reconcile_immutable();
